    /// **`openmir2-m3-attack-magic-wiring`（第一片）**：`CM_HIT`/`CM_HEAVYHIT` 派发——
    /// `nX==CurrX && nY==CurrY` 成功门、`Death` 守卫、前方格取目标并 `attack_cmd`、
    /// 给附近观察者发 `SM_HIT` 族动作帧（无尾，排除自己）、给自己回 `+GD`。
    ///
    /// 红检：① `attackwire::at_self` 改成恒 `true` ⇒ 段 ① 的「不回 ack」必红；
    /// ② `attackwire::hit_mode` 把 `CM_HEAVYHIT` 映射成 0 ⇒ 段 ③ 的 `SM_HEAVYHIT` 断言必红；
    /// ③ `attackwire::front_position` 的 `DIR_UP` 支改成 `(x, y - 2)`（或
    /// `smframe::sm_action_hit` 头字段互换）⇒ 段 ② 的「目标被击中」/帧头断言必红；
    /// ④ 取目标改回用**本帧消息 dir**（`front_position(dir, …)` 而非 `pose_dir`）⇒ 段 ② 必红
    /// （本帧 dir=4=下 与状态化朝向 0=上 相反，怪在正上方 ⇒ 不再命中；oracle
    /// `PlayObject.Attack.cs:26` 在 `BaseObject.Attack.cs:12` 的 `Dir = nDir` 之前取目标）。
    #[test]
    fn hit_cmd_dispatches_ack_action_frame_and_world_attack() {
        use mir2_protocol::messages::{CM_HEAVYHIT, CM_HIT, SM_HEAVYHIT, SM_HIT};
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let attacker = {
            let mut e = mir2_world::Entity::new(0, "atk".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e.dc = 0x0064; // DC 100
            world.add_entity(e)
        };
        let observer = {
            let mut e = mir2_world::Entity::new(0, "obs".to_string(), 12, 12);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let monster = {
            let mut e = mir2_world::Entity::new(0, "mon".to_string(), 10, 9); // 正上方（Dir=0）
            e.race = mir2_world::ACTOR_RACE_MONSTER;
            e.hp = 200;
            e.max_hp = 200;
            e.hit_point = 0; // `BaseObject.Attack.cs:39` 的命中判定：HitPoint==0 ⇒ 必中
            e.speed_point = 15;
            world.add_entity(e)
        };
        world.tick(); // Enter 落格
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            attacker,
            // 状态化 `Dir` = 0（上）= 怪物所在方向；本帧消息 dir 段 ② 用 4（下）以区分两者。
            downlink::ActorDisplay::new(0, 0, 111, 0, 0, 255, b"atk".to_vec()),
        );
        displays.set(
            observer,
            downlink::ActorDisplay::new(4, 0, 222, 0, 0, 255, b"obs".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "atk".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: attacker,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "ub".into(),
                chr_name: "obs".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 902,
                actor_id: observer,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("atk".into(), test_session_ground(attacker));

        // ① 目标格 != 自身（(11,10)）⇒ 不攻击、不回 ack、不发帧。
        let rejected = handle_hit_cmd(
            CM_HIT,
            game_svr::feature::make_long(11, 10),
            0,
            "atk",
            901,
            &online,
            &mut world,
            &mut displays,
            &mut sessions,
            &gates,
            &game_svr::ability::StdItemCatalog::new(),
        );
        assert!(rx0.try_recv().is_err(), "目标≠自身 ⇒ 不得回 ack / 发帧");
        assert!(
            !rejected,
            "被守卫拒的一击必须返回 false（无攻击单元 ⇒ 调用方不落服务端状态 dump 行）"
        );

        // ② 目标格 = 自身 ⇒ SM_HIT 动作帧给观察者 + +GD 给自己 + 攻击入队（tick 后结算）。
        let per_before = sessions["atk"].recovery.per_health;
        let swung = handle_hit_cmd(
            CM_HIT,
            game_svr::feature::make_long(10, 10),
            4, // 本帧消息 dir = 下（与状态化朝向 0=上 相反）⇒ 取目标必须用状态化朝向才击中正上方怪
            "atk",
            901,
            &online,
            &mut world,
            &mut displays,
            &mut sessions,
            &gates,
            &game_svr::ability::StdItemCatalog::new(),
        );
        let (mut frames, mut ack) = (Vec::new(), None);
        while let Ok(m) = rx0.try_recv() {
            match m {
                SimToGate::SendFrame { socket, body } => {
                    assert_eq!(socket, 902, "动作帧只给观察者");
                    frames.push(body);
                }
                SimToGate::SendRaw { socket, payload } => {
                    assert_eq!(socket, 901, "+GD 只给发起者自己");
                    ack = Some(payload);
                }
                other => panic!("意外 sim→gate 命令：{other:?}"),
            }
        }
        assert_eq!(frames.len(), 1, "CM_HIT ⇒ 只一帧 SM_HIT（无尾）");
        assert!(
            swung,
            "进入攻击路径的一击必须返回 true（owner 2026-10-12 23:50 第 ③ 条：调用方据此落
             SERVER_STATE dump 行；恒 false ⇒ 夹具的服务端状态门永远拿不到 Rust 行）"
        );
        assert_eq!(
            &frames[0][..12],
            // 动作帧 `Dir` 用**新** Dir（= 本帧消息 dir=4；`PlayObject.Attack.cs:76`）。
            &smframe::command_header(attacker, SM_HIT, 10, 10, 4)
        );
        assert_eq!(frames[0].len(), 12, "SM_HIT 无尾");
        assert!(ack.expect("+GD").starts_with(b"+GD/"));
        assert_eq!(
            sessions["atk"].recovery.per_health,
            per_before.wrapping_sub(2),
            "成功支 PerHealth -= 2（oracle 无符号回绕）"
        );
        // 本片（`openmir2-m3-scoped-diff-ability`）：成功支的体力/魔力点（`PlayObject.Attack.cs:955-957`）。
        assert_eq!(
            sessions["atk"].stamina.health_tick, -30,
            "成功支 HealthTick -= 30（初始 0 ⇒ -30）"
        );
        assert_eq!(
            sessions["atk"].stamina.spell_tick, 0,
            "成功支 SpellTick -= 100 ⇒ max(0, ...)（初始 0 ⇒ 0）"
        );
        let rec = world.tick();
        assert!(
            rec.attacks
                .iter()
                .any(|(a, t, _)| *a == attacker && *t == monster),
            "攻击必须落到正上方怪：{rec:?}"
        );
        assert!(
            world.entities.get(monster).unwrap().hp < 200,
            "命中应扣血（DC=100 vs AC=0）"
        );

        // ③ CM_HEAVYHIT ⇒ 观察者收 SM_HEAVYHIT(15)。
        handle_hit_cmd(
            CM_HEAVYHIT,
            game_svr::feature::make_long(10, 10),
            0,
            "atk",
            901,
            &online,
            &mut world,
            &mut displays,
            &mut sessions,
            &gates,
            &game_svr::ability::StdItemCatalog::new(),
        );
        let mut heavy = None;
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, .. } = m {
                heavy = Some(body);
            }
        }
        let heavy = heavy.expect("CM_HEAVYHIT ⇒ 观察者收帧");
        assert_eq!(
            u16::from_le_bytes([heavy[4], heavy[5]]),
            SM_HEAVYHIT,
            "CM_HEAVYHIT ⇒ `GetHitMode(1)` = RM_HEAVYHIT ⇒ SM_HEAVYHIT"
        );

        // ④ Death 守卫 ⇒ 不发帧/不回 ack。
        world.entities.get_mut(attacker).unwrap().death = true;
        handle_hit_cmd(
            CM_HIT,
            game_svr::feature::make_long(10, 10),
            0,
            "atk",
            901,
            &online,
            &mut world,
            &mut displays,
            &mut sessions,
            &gates,
            &game_svr::ability::StdItemCatalog::new(),
        );
        assert!(rx0.try_recv().is_err(), "Death ⇒ 不得发帧/回 ack");
    }

    /// 数出两次 RNG 快照之间消耗的**内部采样次数**：`RandomNumber` 的完整 state 由 `Debug` 暴露，
    /// 同一 seed 的参照流走 k 步后 state 必然相同 ⇒ 直接线性求解 k。
    /// 无目标一击（小范围 `random_below`）每次恰 1 个内部采样 ⇒ 该值即「抽数」（= 账本的一段）。
    fn draws_between(
        before: &mir2_shared::rng::RandomNumber,
        after: &mir2_shared::rng::RandomNumber,
    ) -> usize {
        let after_state = format!("{after:?}");
        let mut probe = before.clone();
        for k in 0..100_000 {
            if format!("{probe:?}") == after_state {
                return k;
            }
            let _ = probe.random();
        }
        panic!("参照流 100000 步内未匹配到目标状态（seed 不同或状态被外部改写）");
    }

    /// **owner 2026-10-12 20:10（M3②③ 关键路径）**：`handle_hit_cmd` 的**无目标支**必须仍走
    /// oracle 的「一击抽攻击力」语义（`World::attack_swing`），否则真机 84/120 空打的取数整段缺失
    /// （C# 120 段 vs Rust 36 段）。
    ///
    /// oracle 锚（逐行）：
    /// - `PlayObject.AttackDir(targetObject = null)`（`PlayObject.Attack.cs:25`）先取目标
    ///   `attackTarget = targetObject ?? GetPoseCreate()`（`:26`）⇒ 前方格无目标 = null；
    /// - 随后 `GetBaseAttackPoewr()` 作为 `GetAttackPowerHit(...)` 的实参被求值（`:73`）⇒
    ///   **攻击力照抽**：玩家 `Luck <= 0` ⇒ `Random(LoByte(DC)+1)` + `Random(10)` 共 2 抽
    ///   （`PlayObject.cs:2929/2932`）；
    /// - `_Attack(null)`（`BaseObject.Attack.cs:32`）与 `AttackSuccess(…, null)`
    ///   （`PlayObject.Attack.cs:215-218` 开头 `return`）都早退 ⇒ 无其它取数。
    ///
    /// 红检：把无目标支的 `world.attack_swing(actor_id)` 删掉（改回「只记日志」）⇒ 世界 RNG 停在
    /// 原位、下面的逐采样状态比对必红。
    #[test]
    fn hit_cmd_without_target_still_draws_attack_power() {
        use mir2_protocol::messages::CM_HIT;
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let attacker = {
            let mut e = mir2_world::Entity::new(0, "atk".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e.dc = 0x1E14; // LoByte=0x14=20、HiByte=0x1E=30 ⇒ (base=20, power=10)
            e.luck = 0;
            e.power_rate = 100;
            world.add_entity(e)
        };
        world.tick();
        // 前方格（dir=2 ⇒ (11,10)）**故意留空** ⇒ `front_target` = None。
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            attacker,
            downlink::ActorDisplay::new(2, 0, 111, 0, 0, 255, b"atk".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "atk".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: attacker,
            },
        );
        let (tx0, _rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("atk".into(), test_session_ground(attacker));

        const SEED: i32 = 20261012;
        world.rng = mir2_shared::rng::RandomNumber::with_seed(SEED);
        // oracle 期望值：玩家 `GetBaseAttackPoewr` 版（`Random(LoByte(DC)+1)` + `Luck<=0` 的
        // `Random(10)`）。用**独立**参照流手推，不由生产 `attack_swing` 反推。
        let mut expected = mir2_shared::rng::RandomNumber::with_seed(SEED);
        let expected_power = mir2_world::combat::get_base_attack_power_player(
            &mut expected,
            0x1E14,
            0,
            100,
            false,
            0,
        );
        assert!(
            (20..=30).contains(&expected_power),
            "DC=0x1E14 ⇒ 攻击力 ∈ [20,30]，实际 {expected_power}"
        );

        let before_one = world.rng.clone();
        handle_hit_cmd(
            CM_HIT,
            game_svr::feature::make_long(10, 10),
            2, // 本帧消息 dir=2（右）⇒ 前方格 (11,10) 无目标
            "atk",
            901,
            &online,
            &mut world,
            &mut displays,
            &mut sessions,
            &gates,
            &game_svr::ability::StdItemCatalog::new(),
        );
        // 改后读数：无目标一击 = 玩家 `GetBaseAttackPoewr` **恰 2 抽**（= 账本的一段）；
        // 改回「只记日志」⇒ 此值为 0（红检实测见证据 `05-redcheck-remove-swing.txt`）。
        let one = draws_between(&before_one, &world.rng);
        println!("ATTACK_SWING_DRAWS_PER_EMPTY_HIT={one}");
        assert_eq!(
            one, 2,
            "无目标一击必须抽 2 次（oracle `PlayObject.Attack.cs:73` 的玩家 GetBaseAttackPoewr）"
        );

        // 同一读数的 84 击外推（真机形态：受害者 36 击后 `death=true` ⇒ 余 84 击空打）：
        // 改后 84 × 2 = 168 抽 / 84 段；改前 0 抽 / 0 段 ⇒ 攻击路径段数 36 → 36 + 84 = 120。
        let before_seq = world.rng.clone();
        for _ in 0..84 {
            handle_hit_cmd(
                CM_HIT,
                game_svr::feature::make_long(10, 10),
                2,
                "atk",
                901,
                &online,
                &mut world,
                &mut displays,
                &mut sessions,
                &gates,
                &game_svr::ability::StdItemCatalog::new(),
            );
        }
        let seq = draws_between(&before_seq, &world.rng);
        println!("ATTACK_SWING_DRAWS_84_EMPTY_HITS={seq}");
        assert_eq!(
            seq,
            84 * 2,
            "84 击空打必须每击抽 2 次（= 84 段，补回 C# 120 vs Rust 36 的缺口）"
        );
    }

    /// **`openmir2-m3-attack-magic-wiring`（第二片）**：`CM_SPELL`/`CM_MAGICKEYCHANGE` 派发——
    /// 守卫（未知魔法号 / `Death` ⇒ 不回 ack）、成功后 `+GD` + `Dir = GetNextDirection`
    /// （**仅 `default` 支的魔号**，见 F-2），以及 `ClientChangeMagicKey` 的魔法键切换（无回帧）。
    ///
    /// 红检：① `magicwire::change_magic_key` 改比 `magic_key` 而不是 `mag_idx` ⇒ 段 ④ 必红；
    /// ② `magicwire::spell_reject` 不看 `has_magic`（未知魔法号也过）⇒ 段 ① 必红；
    /// ③（旧 F-2 收口）`magicwire::EXPLICIT_CASE_MAG_IDX` 里任一魔号改错 ⇒ 段 ⑤ 与
    ///   `magicwire::tests::default_dir_only_for_non_explicit_case_magics` 必红。
    #[test]
    fn spell_cmd_dispatches_guard_ack_and_magic_key_change() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let caster = {
            let mut e = mir2_world::Entity::new(0, "caster".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            caster,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: 1,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        const FIREBALL: u16 = 1;
        // ⑨-2 第②片新增入参：本用例的魔号（1/99/12）都不是召唤面 ⇒ 空表即等价。
        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        let catalog = game_svr::ability::StdItemCatalog::new();
        let magic_table = magics::MagicTable::default();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let registry: Option<mir2_envir::MapRegistry> = None;
        let table = game_svr::mongen::MonsterTable::new(Vec::new());

        // ① 未知魔法号（守卫 NoMagic）⇒ 不回 ack。
        handle_spell_cmd(
            game_svr::feature::make_long(12, 10),
            99,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            registry.as_ref(),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        assert!(rx0.try_recv().is_err(), "未知魔法号 ⇒ 不回 ack / 无帧");

        // ② 有该魔法 + 目标在右 ⇒ 回 `+GD`，且展示方向朝向目标（`GetNextDirection`）。
        handle_spell_cmd(
            game_svr::feature::make_long(12, 10),
            FIREBALL,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            registry.as_ref(),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        match rx0.try_recv() {
            Ok(SimToGate::SendRaw { socket, payload }) => {
                assert_eq!(socket, 911, "+GD 只给发起者自己");
                assert!(payload.starts_with(b"+GD/"), "成功支回 +GD");
            }
            other => panic!("CM_SPELL 成功支应回 +GD：{other:?}"),
        }
        assert!(
            rx0.try_recv().is_err(),
            "本片不发任何魔法帧（效果体未接，登记）"
        );
        assert_eq!(
            displays.get(caster).unwrap().dir,
            game_svr::movewire::DIR_RIGHT,
            "default 支 `Dir = GetNextDirection(10,10 → 12,10)` = 右"
        );

        // ③ `Death` 守卫 ⇒ 不回 ack。
        world.entities.get_mut(caster).unwrap().death = true;
        handle_spell_cmd(
            game_svr::feature::make_long(12, 10),
            FIREBALL,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            registry.as_ref(),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        assert!(rx0.try_recv().is_err(), "Death ⇒ 不回 ack");
        world.entities.get_mut(caster).unwrap().death = false;

        // ④ `CM_MAGICKEYCHANGE`：命中 `mag_idx == Recog` ⇒ 改 `Key`；无回帧。
        handle_magic_key_cmd(1, u16::from(b'f'), "caster", 911, &mut saves);
        assert_eq!(
            saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .magic_key,
            u16::from(b'f'),
            "ClientChangeMagicKey 置 Key"
        );
        assert!(
            rx0.try_recv().is_err(),
            "改魔法键不发帧（oracle 无 SendSocket）"
        );
        // 未命中 ⇒ 不改、也不红。
        handle_magic_key_cmd(42, u16::from(b'z'), "caster", 911, &mut saves);
        assert_eq!(
            saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .magic_key,
            u16::from(b'f'),
            "未命中不改已有键"
        );

        // ⑤ F-2 收口（reviewer-5 `1de8fca5`）：`switch(MagIdx)` 有 8 条独立 `case` 的魔号不套用
        //    `default` 的 `Dir`。补一个 SKILL_ERGUM(12)，把展示方向置为左，再打右侧目标。
        saves.get_mut("caster").unwrap().record.data.magic = Some(vec![
            Some(record::MagicRcd {
                mag_idx: 1,
                level: 1,
                magic_key: u16::from(b'f'),
                tran_point: 0,
            }),
            Some(record::MagicRcd {
                mag_idx: 12,
                level: 1,
                magic_key: u16::from(b'e'),
                tran_point: 0,
            }),
        ]);
        displays.set(
            caster,
            downlink::ActorDisplay::new(
                game_svr::movewire::DIR_LEFT,
                0,
                111,
                0,
                0,
                255,
                b"caster".to_vec(),
            ),
        );
        handle_spell_cmd(
            game_svr::feature::make_long(12, 10),
            12,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            registry.as_ref(),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        match rx0.try_recv() {
            Ok(SimToGate::SendRaw { socket, payload }) => {
                assert_eq!(socket, 911);
                assert!(
                    payload.starts_with(b"+GD/"),
                    "有独立 case 的魔号仍过守卫并回 +GD"
                );
            }
            other => panic!("CM_SPELL(12) 成功支应回 +GD：{other:?}"),
        }
        assert_eq!(
            displays.get(caster).unwrap().dir,
            game_svr::movewire::DIR_LEFT,
            "F-2：mag_idx=12 有独立 case ⇒ 不套用 default 的 Dir（方向保持左）"
        );
    }

    /// **片 A-5 主机层牙**的共用布置（fixture）：buff tick 开启的 64×64 世界 + 施法者 `caster`(10,10)
    /// + 一名目标玩家 `target`（坐标由入参给）+ 在线登记 / 会话 / gate 通道 / 含 `magic_id` 的存档与魔法表。
    ///
    /// 返回 `(world, caster, target, online, saves, magic_table, displays, gates, rx0)`。
    /// `world.enable_buff_tick()` 对应生产宿主 `main.rs:7823`（A-5 路径的运行前提）。
    #[allow(clippy::type_complexity)]
    fn a5_spell_rig(
        magic_id: u16,
        target_x: i32,
        target_y: i32,
    ) -> (
        mir2_world::World,
        i32,
        i32,
        OnlineRegistry,
        std::collections::HashMap<String, SavedHuman>,
        magics::MagicTable,
        downlink::DisplayTable,
        std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        mpsc::UnboundedReceiver<SimToGate>,
    ) {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        // 生产宿主 `main.rs:7823` 的 `world.enable_buff_tick()` —— A-5 支的运行前提。
        // 缺省（关闭）时 A-5 支整段不执行（与既有 golden 逐字节不变的口径一致）。
        world.enable_buff_tick();
        let caster = world.add_entity(new_player_entity("caster".to_string(), 10, 10));
        let target = world.add_entity(new_player_entity("target".to_string(), target_x, target_y));
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            caster,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
        );
        displays.set(
            target,
            downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"target".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "ut".into(),
                chr_name: "target".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 912,
                actor_id: target,
            },
        );
        let (tx0, rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: magic_id,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        // `GetMagicInfo(魔法号)` 的表项（A-5 支取 `magic_table.get(req.magic_id)`）。
        let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id,
            effect: 3,
            effect_type: 4,
            train_lv: 3,
            ..mir2_data::MagicInfo::default()
        }]);
        (
            world,
            caster,
            target,
            online,
            saves,
            magic_table,
            displays,
            gates,
            rx0,
        )
    }

    /// 把 gate 通道上的帧全部取空，返回各帧的 `ident`（`body[4..6]`，与文件末既有用例同口径；
    /// 非 `SendFrame` 的 `SendRaw`（`+GD` ack）不计入）。
    fn a5_take_idents(rx: &mut mpsc::UnboundedReceiver<SimToGate>) -> Vec<u16> {
        let mut ids = Vec::new();
        while let Ok(m) = rx.try_recv() {
            if let SimToGate::SendFrame { body, .. } = m {
                ids.push(u16::from_le_bytes([body[4], body[5]]));
            }
        }
        ids
    }

    // ==========================================================================
    // P2（`openmir2-spell-shared-tail-p2`）：14/15 护身符门 + 14/15/31 共享尾
    // ==========================================================================
    //
    // 全部走**生产入口** `handle_spell_cmd`（`world.enable_buff_tick()` = A-5 支的运行前提）。
    // oracle 锚：`MagicManager.cs:315-393`（13..=19 组：`:322 boSpellFail=true` →
    // `CheckAmulet(1,1)` → `UseAmulet(1,1)` → 各 case 效果 → `:391 boSpellFail=false`）、
    // `:474-479`（31 无护身符/不置 boSpellFail）、`:644-669`（共享尾）、
    // `MagicBase.cs:47-127`（CheckAmulet/UseAmulet）、`CharacterObject.cs:96-114`
    // （`MagBubbleDefenceUp`：`BubbleDefenceUP == 0` ⇒ 恒 true）。

    /// A-5 的**护身符目录**（`CheckAmulet` 的 `StdMode == 25 && Shape == 5` 两门）。
    fn a5_amulet_catalog() -> game_svr::ability::StdItemCatalog {
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "护身符".into(),
                std_mode: 25,
                shape: 5,
                ..mir2_data::StdItem::default()
            },
        );
        catalog
    }

    /// A-5 会话态 + `ArmRingl`（槽 5）护身符（`MakeIndex = Index = 1`）。
    fn a5_session_with_amulet(caster: i32, dura: u16) -> SessionGround {
        let mut sg = spell_session_ground(caster);
        sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
            make_index: 1,
            index: 1,
            dura,
            dura_max: 1000,
            desc: [0; 14],
        });
        sg
    }

    /// P2 专用夹具：buff tick 开启 + 施法者 `caster`(10,10) + 目标 `target`(x,y) +
    /// 可选 `ArmRingl` 护身符 + 可配训练门（`TrainLevel`/`MaxTrain`）。
    ///
    /// 与 [`a5_spell_rig`] 的差别：本夹具接受 seed / 训练门 / 护身符耐久，便于在同一测试里
    /// 跑「门开」与「门关」两条**同种子**对照流（断言必须比较整段流水，不用单抽）。
    struct P2Rig {
        world: mir2_world::World,
        caster: i32,
        target: i32,
        online: OnlineRegistry,
        saves: std::collections::HashMap<String, SavedHuman>,
        ground_sessions: std::collections::HashMap<String, SessionGround>,
        magic_table: magics::MagicTable,
        displays: downlink::DisplayTable,
        gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        catalog: game_svr::ability::StdItemCatalog,
    }

    impl P2Rig {
        #[allow(clippy::too_many_arguments)]
        fn new(
            magic_id: u16,
            target_x: i32,
            target_y: i32,
            amulet_dura: Option<u16>,
            train_level: [u8; 4],
            max_train: [i32; 4],
            seed: i32,
        ) -> Self {
            use std::collections::HashMap;
            let mut world = mir2_world::World::new(64, 64);
            world.enable_buff_tick();
            let caster = world.add_entity(new_player_entity("caster".to_string(), 10, 10));
            let target =
                world.add_entity(new_player_entity("target".to_string(), target_x, target_y));
            world.tick();
            let mut displays = downlink::DisplayTable::new();
            displays.set(
                caster,
                downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
            );
            displays.set(
                target,
                downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"target".to_vec()),
            );
            let mut online: OnlineRegistry = Vec::new();
            online_set(
                &mut online,
                OnlineEntry {
                    account: "uc".into(),
                    chr_name: "caster".into(),
                    session_id: 1,
                    gate_idx: 0,
                    socket: 911,
                    actor_id: caster,
                },
            );
            online_set(
                &mut online,
                OnlineEntry {
                    account: "ut".into(),
                    chr_name: "target".into(),
                    session_id: 2,
                    gate_idx: 0,
                    socket: 912,
                    actor_id: target,
                },
            );
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            let mut saves: HashMap<String, SavedHuman> = HashMap::new();
            let mut record = stage6_record();
            record.data.magic = Some(vec![Some(record::MagicRcd {
                mag_idx: magic_id,
                level: 1,
                magic_key: u16::from(b'm'),
                tran_point: 0,
            })]);
            saves.insert(
                "caster".into(),
                SavedHuman {
                    account: "uc".into(),
                    record,
                    enter_map: "0".into(),
                },
            );
            let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
                magic_id,
                effect: 3,
                effect_type: 4,
                train_lv: 3,
                train_level,
                max_train,
                ..mir2_data::MagicInfo::default()
            }]);
            let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
            let sg = match amulet_dura {
                Some(dura) => a5_session_with_amulet(caster, dura),
                None => spell_session_ground(caster),
            };
            ground_sessions.insert("caster".into(), sg);
            let mut world = world;
            world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
            Self {
                world,
                caster,
                target,
                online,
                saves,
                ground_sessions,
                magic_table,
                displays,
                gates,
                rx,
                catalog: a5_amulet_catalog(),
            }
        }

        fn cast(&mut self, magic_id: u16, click: (u16, u16), target_actor_id: u16) {
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            handle_spell_cmd(
                game_svr::feature::make_long(click.0, click.1),
                magic_id,
                target_actor_id,
                0,
                "caster",
                911,
                &self.online,
                &mut self.world,
                &mut self.saves,
                &mut self.ground_sessions,
                &self.catalog,
                &self.magic_table,
                &pet_cfg,
                8,
                None,
                &table,
                &mut self.displays,
                &self.gates,
                1,
                1,
                2,
            );
        }

        fn drain_frames(&mut self) -> Vec<SfFrame> {
            let mut frames = Vec::new();
            while let Ok(m) = self.rx.try_recv() {
                if let SimToGate::SendFrame { socket, body } = m {
                    frames.push((socket, body));
                }
            }
            frames
        }

        fn amulet_dura(&self) -> Option<u16> {
            self.ground_sessions
                .get("caster")
                .and_then(|sg| sg.use_items[game_svr::ability::SLOT_ARMRING_L].as_ref())
                .map(|it| it.dura)
        }

        fn tran_point(&self) -> i32 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .tran_point
        }

        fn tran_level(&self) -> u8 {
            self.saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .level
        }
    }

    /// `SM_DURACHANGE(642)` 的载荷：`(Dura, Slot, DuraMax)`。
    fn p2_durachange_fields(b: &[u8]) -> (i32, u16, u16) {
        let cmd = mir2_protocol::frame::CommandMessage::from_bytes(b).unwrap();
        (cmd.recog, cmd.param, cmd.tag)
    }

    /// 全局发送序（同一 gate 通道 = 同一次 `handle_spell_cmd` 的发送调用序）。
    fn p2_seq(frames: &[SfFrame]) -> Vec<u16> {
        frames.iter().map(|(_, b)| sf_ident(b)).collect()
    }

    fn p2_pos(seq: &[u16], ident: u16, why: &str) -> usize {
        seq.iter()
            .position(|x| *x == ident)
            .unwrap_or_else(|| panic!("{why}：序列里没有 ident {ident}；实得 {seq:?}"))
    }

    /// **P2-① 护身符消耗 + 共享尾（14/15）**：`Dura=600` ⇒ 恰减 100（→500）+ **仅自己**一条
    /// `SM_DURACHANGE(642)`；buff 生效；`SM_SPELL`→`SM_DURACHANGE`→`SM_MAGICFIRE`→`SM_MAGIC_LVEXP`
    /// 的发送序；训练门开 ⇒ 比同种子「门关」流**恰多一次** `Random(3)+1`，`TranPoint` 回写 = 该抽。
    ///
    /// 红检（实测见补丁说明）：③ 去掉尾调用 ⇒ 观察者 `SM_MAGICFIRE` 变 0、无 LVEXP ⇒ 红；
    /// ④ 把尾挪到护身符门之前 ⇒ 无护身符用例的零抽/无 MAGICFIRE 断言红。
    #[test]
    fn spell_tail_p2_defence_amulet_consumed_and_tail_fires() {
        for magic_id in [14u16, 15] {
            let seed = 8100 + i32::from(magic_id);
            let mut rig = P2Rig::new(
                magic_id,
                12,
                12,
                Some(600),
                [0; 4],
                [0, 1000, 1000, 1000],
                seed,
            );
            let before = rig.world.rng.clone();
            let target = u16::try_from(rig.target).unwrap();
            rig.cast(magic_id, (12, 12), target);
            let frames = rig.drain_frames();

            // 护身符：600 > 1*100 ⇒ 500 + SM_DURACHANGE（仅自己）。
            assert_eq!(
                rig.amulet_dura(),
                Some(500),
                "[魔号 {magic_id}] UseAmulet(1,1) ⇒ Dura 恰减 100"
            );
            assert_eq!(
                sf_count(&frames, 911, mir2_protocol::messages::SM_DURACHANGE),
                1,
                "[魔号 {magic_id}] 施法者恰 1 条 SM_DURACHANGE"
            );
            assert_eq!(
                sf_count(&frames, 912, mir2_protocol::messages::SM_DURACHANGE),
                0,
                "[魔号 {magic_id}] `SendMsg(this, RM_DURACHANGE)` ⇒ 观察者不收"
            );
            let dc = sf_first(&frames, 911, mir2_protocol::messages::SM_DURACHANGE);
            assert_eq!(
                p2_durachange_fields(dc),
                (
                    500,
                    u16::from(game_svr::ability::SLOT_ARMRING_L as u8),
                    1000
                ),
                "[魔号 {magic_id}] SM_DURACHANGE = (Dura, idx, DuraMax)"
            );

            // buff 生效（14 ⇒ MagDefenceUp；15 ⇒ DefenceUp）。
            match magic_id {
                14 => assert!(
                    rig.world
                        .buffs
                        .has_buff(rig.target, mir2_world::BuffType::MagicDefensePower),
                    "14 `MagMakeDefenceArea(..., btState=1)` ⇒ 目标获 MagicDefensePower"
                ),
                _ => assert!(
                    rig.world
                        .buffs
                        .has_buff(rig.target, mir2_world::BuffType::DefensePower),
                    "15 `MagMakeDefenceArea(..., btState=0)` ⇒ 目标获 DefensePower"
                ),
            }

            // 帧面：广播 SM_SPELL 排除自己；SM_MAGICFIRE 含自己；LVEXP 仅自己。
            assert_eq!(sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL), 1);
            assert_eq!(
                sf_count(&frames, 911, mir2_protocol::messages::SM_SPELL),
                0,
                "RM_SPELL 有自守卫 ⇒ 自己不收"
            );
            assert_eq!(
                sf_count(&frames, 912, mir2_protocol::messages::SM_MAGICFIRE),
                1,
                "[魔号 {magic_id}] 观察者恰 1 条 SM_MAGICFIRE"
            );
            assert_eq!(
                sf_count(&frames, 911, mir2_protocol::messages::SM_MAGICFIRE),
                1,
                "[魔号 {magic_id}] 自己恰 1 条 SM_MAGICFIRE（处理器无自守卫）"
            );
            assert_eq!(
                sf_count(&frames, 911, mir2_protocol::messages::SM_MAGIC_LVEXP),
                1,
                "[魔号 {magic_id}] 训练门开 ⇒ 恰 1 条 SM_MAGIC_LVEXP"
            );
            assert_eq!(
                sf_count(&frames, 912, mir2_protocol::messages::SM_MAGIC_LVEXP),
                0
            );
            let fire = sf_first(&frames, 912, mir2_protocol::messages::SM_MAGICFIRE);
            assert_eq!(
                sf_magicfire_target_id(fire),
                rig.target,
                "[魔号 {magic_id}] 活目标 ⇒ RM_MAGICFIRE ActorId = 目标 id"
            );

            // 发送序：SM_SPELL → SM_DURACHANGE → SM_MAGICFIRE → SM_MAGIC_LVEXP。
            let seq = p2_seq(&frames);
            let i_spell = p2_pos(&seq, mir2_protocol::messages::SM_SPELL, "SM_SPELL");
            let i_dura = p2_pos(
                &seq,
                mir2_protocol::messages::SM_DURACHANGE,
                "SM_DURACHANGE",
            );
            let i_fire = p2_pos(&seq, mir2_protocol::messages::SM_MAGICFIRE, "SM_MAGICFIRE");
            let i_lv = p2_pos(
                &seq,
                mir2_protocol::messages::SM_MAGIC_LVEXP,
                "SM_MAGIC_LVEXP",
            );
            assert!(
                i_spell < i_dura && i_dura < i_fire && i_fire < i_lv,
                "[魔号 {magic_id}] 帧序必须 SM_SPELL < SM_DURACHANGE < SM_MAGICFIRE < SM_MAGIC_LVEXP；实得 {seq:?}"
            );

            // 训练尾：门开 vs 同种子门关（`TrainLevel[1]=255 > Abil.Level`）恰多一次抽。
            let draws_open = draws_between(&before, &rig.world.rng);
            let tp = rig.tran_point();
            assert!(
                (1..=3).contains(&tp),
                "[魔号 {magic_id}] TranPoint 增量 = Random(3)+1 ∈ [1,3]；实得 {tp}"
            );
            let mut closed = P2Rig::new(
                magic_id,
                12,
                12,
                Some(600),
                [0, 255, 0, 0],
                [0, 1000, 1000, 1000],
                seed,
            );
            let before_c = closed.world.rng.clone();
            closed.cast(magic_id, (12, 12), target);
            let frames_c = closed.drain_frames();
            let draws_closed = draws_between(&before_c, &closed.world.rng);
            assert_eq!(
                draws_open,
                draws_closed + 1,
                "[魔号 {magic_id}] 训练门开 ⇒ 比门关流恰多一次 Random(3)+1"
            );
            assert_eq!(closed.tran_point(), 0, "门关 ⇒ TranPoint 不变");
            assert_eq!(
                sf_count(&frames_c, 911, mir2_protocol::messages::SM_MAGIC_LVEXP),
                0,
                "门关 ⇒ 无 LVEXP"
            );
            assert_eq!(
                sf_count(&frames_c, 912, mir2_protocol::messages::SM_MAGICFIRE),
                1,
                "训练门不影响尾的 RM_MAGICFIRE"
            );
            // 完整流水：同种子跳过效果体取数后，下一次恰是 Random(3)+1。
            let mut ctl = mir2_shared::rng::RandomNumber::with_seed(seed);
            for _ in 0..draws_closed {
                ctl.random();
            }
            assert_eq!(
                tp,
                ctl.random_below(3) + 1,
                "[魔号 {magic_id}] TranPoint = 门内 Random(3)+1（整段流水位置正确）"
            );
            for k in 0..3 {
                assert_eq!(
                    rig.world.rng.random(),
                    ctl.random(),
                    "[魔号 {magic_id}] 尾后第 {k} 抽必须与对照流一致（禁止错位）"
                );
            }
            // `max_train[1] = 1000` ⇒ 不升级，LVEXP 载荷 = (MagicId, Level=1, TranPoint)。
            assert_eq!(rig.tran_level(), 1, "[魔号 {magic_id}] 点数不足 ⇒ 不升级");
            let lv = sf_first(&frames, 911, mir2_protocol::messages::SM_MAGIC_LVEXP);
            let cmd = mir2_protocol::frame::CommandMessage::from_bytes(lv).unwrap();
            assert_eq!(cmd.recog, i32::from(magic_id), "LVEXP Recog = MagicId");
            assert_eq!(cmd.param, 1, "LVEXP Param = Level");
            assert_eq!(
                i32::from(cmd.tag) | (i32::from(cmd.series) << 16),
                tp,
                "LVEXP Tag/Series = TranPoint"
            );
        }
    }

    /// **P2-② 护身符的两处边界（Round 与 UseAmulet 的 else 支）**。
    ///
    /// oracle `CheckAmulet` 用 `HUtil32.Round(Dura / 100.0) >= 1`，而 `HUtil32.Round`
    /// （`src/OpenMir2/HUtil32.cs:131-134`）是 `MidpointRounding.AwayFromZero` ⇒
    /// **Dura=50 ⇒ Round(0.5)=1 ⇒ 门过**（不是 0）；Dura=49 ⇒ 0 ⇒ 门不过。
    /// `UseAmulet`（`MagicBase.cs:116-126`）的边界是 `Dura > 100`：Dura=50/100 都走
    /// **else 支**（`Dura=0` + `SendDelItems` + `Index=0`），Dura=101 走扣减支（→1）。
    ///
    /// 红检（实测见补丁说明）：① 去掉护身符门 ⇒ Dura=49 用例「无 buff/639」红。
    #[test]
    fn spell_tail_p2_amulet_rounding_and_delete_boundaries() {
        // (Dura, 门是否通过)
        for (dura, passes) in [(49u16, false), (50, true), (100, true), (101, true)] {
            let magic_id = 15u16;
            let seed = 8200 + i32::from(dura);
            let mut rig = P2Rig::new(
                magic_id,
                12,
                12,
                Some(dura),
                [0; 4],
                [0, 1000, 1000, 1000],
                seed,
            );
            let before = rig.world.rng.clone();
            let target = u16::try_from(rig.target).unwrap();
            rig.cast(magic_id, (12, 12), target);
            let frames = rig.drain_frames();

            if !passes {
                assert_eq!(
                    rig.amulet_dura(),
                    Some(49),
                    "[Dura=49] 门不过 ⇒ 不得扣耐久/清槽"
                );
                assert_eq!(
                    draws_between(&before, &rig.world.rng),
                    0,
                    "[Dura=49] 门不过 ⇒ 世界 RNG 零抽（不上 buff、不走尾）"
                );
                assert!(
                    !rig.world
                        .buffs
                        .has_buff(rig.target, mir2_world::BuffType::DefensePower),
                    "[Dura=49] 门不过 ⇒ 目标不得获 buff"
                );
                for socket in [911, 912] {
                    assert_eq!(
                        sf_count(&frames, socket, mir2_protocol::messages::SM_MAGICFIRE_FAIL),
                        1,
                        "[Dura=49] socket {socket} 恰一条 639"
                    );
                    assert_eq!(
                        sf_count(&frames, socket, mir2_protocol::messages::SM_MAGICFIRE),
                        0,
                        "[Dura=49] 不得发 SM_MAGICFIRE"
                    );
                    assert_eq!(
                        sf_count(&frames, socket, mir2_protocol::messages::SM_MAGIC_LVEXP),
                        0
                    );
                }
                // `SM_SPELL`（:159）先于护身符门 ⇒ 观察者仍收到恰 1 条；自己在 639 之前不收。
                assert_eq!(sf_count(&frames, 912, mir2_protocol::messages::SM_SPELL), 1);
                continue;
            }

            // 门过：buff + 尾。
            assert!(
                rig.world
                    .buffs
                    .has_buff(rig.target, mir2_world::BuffType::DefensePower),
                "[Dura={dura}] 门过 ⇒ buff 生效"
            );
            assert!(
                draws_between(&before, &rig.world.rng) > 0,
                "[Dura={dura}] 门过 ⇒ 效果体取数"
            );
            assert_eq!(
                sf_count(&frames, 912, mir2_protocol::messages::SM_MAGICFIRE),
                1
            );
            assert_eq!(
                sf_count(&frames, 911, mir2_protocol::messages::SM_MAGIC_LVEXP),
                1
            );
            assert_eq!(
                sf_count(&frames, 911, mir2_protocol::messages::SM_MAGICFIRE_FAIL),
                0,
                "[Dura={dura}] 门过 ⇒ 无 639"
            );
            if dura > 100 {
                // 扣减支：101 → 1，并发 SM_DURACHANGE。
                assert_eq!(rig.amulet_dura(), Some(dura - 100));
                assert_eq!(
                    sf_count(&frames, 911, mir2_protocol::messages::SM_DURACHANGE),
                    1
                );
                assert_eq!(
                    sf_count(&frames, 911, mir2_protocol::messages::SM_DELITEM),
                    0
                );
                let dc = sf_first(&frames, 911, mir2_protocol::messages::SM_DURACHANGE);
                assert_eq!(
                    p2_durachange_fields(dc),
                    (
                        i32::from(dura - 100),
                        u16::from(game_svr::ability::SLOT_ARMRING_L as u8),
                        1000
                    )
                );
            } else {
                // else 支：Dura=0 + SendDelItems + Index=0 ⇒ SM_DELITEM(202) 仅自己。
                assert_eq!(
                    rig.amulet_dura(),
                    None,
                    "[Dura={dura}] `Dura > 100` 假 ⇒ 清槽（Index=0 ⇒ 槽 None）"
                );
                assert_eq!(
                    sf_count(&frames, 911, mir2_protocol::messages::SM_DELITEM),
                    1,
                    "[Dura={dura}] 恰一条 SM_DELITEM"
                );
                assert_eq!(
                    sf_count(&frames, 912, mir2_protocol::messages::SM_DELITEM),
                    0
                );
                assert_eq!(
                    sf_count(&frames, 911, mir2_protocol::messages::SM_DURACHANGE),
                    0,
                    "[Dura={dura}] else 支不发 SM_DURACHANGE"
                );
            }
        }
    }

    /// **P2-③ 14/15 无护身符**：不上 buff、不走尾（零抽、无 `SM_MAGICFIRE`/`SM_MAGIC_LVEXP`）、
    /// 每收件人**恰一条** `SM_MAGICFIRE_FAIL(639)`；`SM_SPELL` 已在更早处（`:159`）发出。
    ///
    /// 红检（实测见补丁说明）：① 去掉护身符门 ⇒ buff/尾/零抽断言红。
    #[test]
    fn spell_tail_p2_no_amulet_blocks_buff_and_tail() {
        for magic_id in [14u16, 15] {
            let seed = 8300 + i32::from(magic_id);
            let mut rig = P2Rig::new(magic_id, 12, 12, None, [0; 4], [0, 1000, 1000, 1000], seed);
            let before = rig.world.rng.clone();
            let target = u16::try_from(rig.target).unwrap();
            rig.cast(magic_id, (12, 12), target);
            let frames = rig.drain_frames();

            for (who, id) in [("target", rig.target), ("caster", rig.caster)] {
                assert!(
                    !rig.world
                        .buffs
                        .has_buff(id, mir2_world::BuffType::DefensePower),
                    "[魔号 {magic_id}] 无护身符 ⇒ {who} 不得获 DefensePower"
                );
                assert!(
                    !rig.world
                        .buffs
                        .has_buff(id, mir2_world::BuffType::MagicDefensePower),
                    "[魔号 {magic_id}] 无护身符 ⇒ {who} 不得获 MagicDefensePower"
                );
            }
            assert_eq!(
                draws_between(&before, &rig.world.rng),
                0,
                "[魔号 {magic_id}] 无护身符 ⇒ 零抽（buff 效果体与训练尾都不得执行）"
            );
            let mut ctl = mir2_shared::rng::RandomNumber::with_seed(seed);
            for k in 0..3 {
                assert_eq!(
                    rig.world.rng.random(),
                    ctl.random(),
                    "[魔号 {magic_id}] 其后第 {k} 抽 == 同种子未施法对照流"
                );
            }
            for socket in [911, 912] {
                assert_eq!(
                    sf_count(&frames, socket, mir2_protocol::messages::SM_MAGICFIRE_FAIL),
                    1,
                    "[魔号 {magic_id}] socket {socket} 恰一条 639"
                );
                assert_eq!(
                    sf_count(&frames, socket, mir2_protocol::messages::SM_MAGICFIRE),
                    0,
                    "[魔号 {magic_id}] 无护身符 ⇒ 无 SM_MAGICFIRE"
                );
                assert_eq!(
                    sf_count(&frames, socket, mir2_protocol::messages::SM_MAGIC_LVEXP),
                    0
                );
                assert_eq!(
                    sf_count(&frames, socket, mir2_protocol::messages::SM_DURACHANGE),
                    0
                );
                assert_eq!(
                    sf_count(&frames, socket, mir2_protocol::messages::SM_DELITEM),
                    0
                );
            }
            // 观察者序：SM_SPELL 先于 639。
            let obs = sf_seq(&frames, 912);
            let i_spell = p2_pos(&obs, mir2_protocol::messages::SM_SPELL, "SM_SPELL");
            let i_fail = p2_pos(
                &obs,
                mir2_protocol::messages::SM_MAGICFIRE_FAIL,
                "SM_MAGICFIRE_FAIL",
            );
            assert!(
                i_spell < i_fail,
                "[魔号 {magic_id}] oracle 序：`:159 SM_SPELL` 先于护身符门失败后的 639；实得 {obs:?}"
            );
            assert_eq!(
                rig.tran_point(),
                0,
                "[魔号 {magic_id}] 无训练尾 ⇒ TranPoint 不变"
            );
            assert_eq!(rig.tran_level(), 1);
        }
    }

    /// **P2-④ 31（魔法盾）无护身符也施放；`bo_train` 恒 true**：
    /// `MagBubbleDefenceUp` 在 `BubbleDefenceUP == 0` 时恒返回 true（`CharacterObject.cs:96-114`）
    /// ⇒ 即使 `n_sec` 为 0 也必须走训练抽；尾帧 `SM_MAGICFIRE` 必发（`boSpellFire=true`）。
    ///
    /// 红检（实测见补丁说明）：② 把 31 的 `bo_train` 写死 `false` ⇒ 本用例「多一次抽/LVEXP」红。
    #[test]
    fn spell_tail_p2_shield_without_amulet_always_trains() {
        let magic_id = 31u16;
        let seed = 8400;
        let mut open = P2Rig::new(magic_id, 12, 12, None, [0; 4], [0, 1000, 1000, 1000], seed);
        let before = open.world.rng.clone();
        let target = u16::try_from(open.target).unwrap();
        open.cast(magic_id, (12, 12), target);
        let frames = open.drain_frames();

        // bubble 效果与现状一致（目标是施法者自己）。
        assert!(
            open.world
                .buffs
                .has_buff(open.caster, mir2_world::BuffType::MagicShield),
            "31 ⇒ 施法者获 MagicShield buff"
        );
        assert!(
            open.world.entities.get(open.caster).unwrap().magic_shield,
            "31 ⇒ `MagicShield` 标志置位"
        );
        assert_eq!(
            sf_count(&frames, 912, mir2_protocol::messages::SM_MAGICFIRE),
            1,
            "31 无护身符门 ⇒ 尾必发恰 1 条 SM_MAGICFIRE（观察者）"
        );
        assert_eq!(
            sf_count(&frames, 911, mir2_protocol::messages::SM_MAGICFIRE),
            1,
            "含施法者自己"
        );
        assert_eq!(
            sf_count(&frames, 911, mir2_protocol::messages::SM_MAGIC_LVEXP),
            1,
            "训练门开 ⇒ 恰 1 条 LVEXP"
        );
        let tp = open.tran_point();
        assert!((1..=3).contains(&tp), "TranPoint = Random(3)+1；实得 {tp}");
        let seq = p2_seq(&frames);
        assert!(
            p2_pos(&seq, mir2_protocol::messages::SM_SPELL, "SM_SPELL")
                < p2_pos(&seq, mir2_protocol::messages::SM_MAGICFIRE, "SM_MAGICFIRE"),
            "帧序 SM_SPELL → SM_MAGICFIRE；实得 {seq:?}"
        );

        // 同种子门关（`TrainLevel[1]=255`）⇒ 恰少一次抽、无 LVEXP；尾帧仍发。
        let mut closed = P2Rig::new(
            magic_id,
            12,
            12,
            None,
            [0, 255, 0, 0],
            [0, 1000, 1000, 1000],
            seed,
        );
        let before_c = closed.world.rng.clone();
        closed.cast(magic_id, (12, 12), target);
        let frames_c = closed.drain_frames();
        let draws_open = draws_between(&before, &open.world.rng);
        let draws_closed = draws_between(&before_c, &closed.world.rng);
        assert_eq!(
            draws_open,
            draws_closed + 1,
            "31 的训练尾在门内恰多一次 Random(3)+1（不许拿 n_sec 当 bo_train）"
        );
        assert_eq!(closed.tran_point(), 0);
        assert_eq!(
            sf_count(&frames_c, 911, mir2_protocol::messages::SM_MAGIC_LVEXP),
            0
        );
        assert_eq!(
            sf_count(&frames_c, 912, mir2_protocol::messages::SM_MAGICFIRE),
            1
        );
        // 完整流水位置：跳过效果体取数后恰是 Random(3)+1。
        let mut ctl = mir2_shared::rng::RandomNumber::with_seed(seed);
        for _ in 0..draws_closed {
            ctl.random();
        }
        assert_eq!(tp, ctl.random_below(3) + 1);
        for k in 0..3 {
            assert_eq!(
                open.world.rng.random(),
                ctl.random(),
                "尾后第 {k} 抽必须与对照流一致"
            );
        }
    }

    /// **片 A-5 主机层牙①（in-range 对照）**：`handle_spell_cmd`（**生产入口**，不直调 `World::cast_*`）
    /// 在 buff tick 开启时把技能 15（`SKILL_DEJIWONHO` → `DefenceUp`）落到目标身上。
    ///
    /// 布置：施法者 (10,10)、目标 (12,12)，`|Δx| = |Δy| = 2 <= MagicAttackRage = 8` ⇒ 过
    /// `DoSpell` 距离门（`src/M2Server/Magic/MagicManager.cs:155`）。
    ///
    /// 断言：① 世界侧可观测的 `World::buffs`（`BuffSystem::has_buff`）在 `(target, DefensePower)` 上为真
    /// （`MagMakeDefenceArea(..., btState = 0)` ⇒ `DefenceUp`）；② 世界 RNG **确有**推进
    /// （`power_defence_area` 的取数：`GetPower13` → `GetAttackPower`）——两者合起来证明 A-5 生产链
    /// 真的从宿主走通到世界。
    ///
    /// 红检（变异牙）：把 A-5 块的 `world.cast_defence_area_spell(...)` 调用去掉 ⇒ ① 必红。
    /// **距离门本身的变异牙**在越界那条（`spell_cmd_a5_defence_area_blocked_out_of_range`）。
    #[test]
    fn spell_cmd_a5_defence_area_buffs_target_in_range() {
        let (
            mut world,
            caster,
            target,
            online,
            mut saves,
            magic_table,
            mut displays,
            gates,
            mut rx0,
        ) = a5_spell_rig(15, 12, 12);
        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        // **牙的布置修正（P2，设计件 §7-10）**：14/15 补 `CheckAmulet(1,1)` 后，夹具必须同时有
        // `ArmRingl` 槽与 catalog 模板（`index=1`、`std_mode=25`、`shape=5`、`dura=600`）；
        // 只加槽不加模板 ⇒ `amulet_slot` 返回 None ⇒ 门不过。
        ground_sessions.insert("caster".into(), a5_session_with_amulet(caster, 600));
        let catalog = a5_amulet_catalog();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        let rng_before = world.rng.clone();
        handle_spell_cmd(
            game_svr::feature::make_long(12, 12),
            15,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            None,
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        assert!(
            world
                .buffs
                .has_buff(target, mir2_world::BuffType::DefensePower),
            "in-range（|Δ|=2 ≤ MagicAttackRage=8）⇒ 目标获 `DefencePower`（技能 15 → `DefenceUp`）"
        );
        assert!(
            draws_between(&rng_before, &world.rng) > 0,
            "过门 ⇒ `power_defence_area` 抽数（世界 RNG 前进）"
        );
        assert!(
            !a5_take_idents(&mut rx0).contains(&mir2_protocol::messages::SM_CHARSTATUSCHANGED),
            "A-5 支不自行发 657（帧面走 `drain_buff_downlink` 读 `TickRecord`，见登记）"
        );
    }

    /// **片 A-5 主机层牙②（F-1 越界门，R 级）**：**同一布置**但目标坐标超出 `MagicAttackRage`（传 8）
    /// ⇒ `DoSpell` 的距离门（`MagicManager.cs:155`）**直接 `return false`**：
    /// ① 目标**不得获得任何 buff**、`MagicShield` 不得置位；② 世界 RNG **一次都不抽**；
    /// ③ 不得有 `SM_CHARSTATUSCHANGED(657)` 下行帧（含本 tick `drain_buff_downlink` 的真实出帧面）。
    ///
    /// 布置上目标实体**确实落在** `(25,25)`（= 施法请求的原始目标坐标）⇒ 若距离门被去掉，
    /// `MagMakeDefenceArea` 的 `(2*3+1)^2 = 49` 次迭代会真的给它加 `DefenceUp`、
    /// `MagBubbleDefenceUp` 会真的给施法者置 `MagicShield` ⇒ ① ② 必红（变异实测见补丁说明）。
    ///
    /// 三个魔号各跑一遍（14/15 走 `MagMakeDefenceArea`；31 走 `MagBubbleDefenceUp` ⇒ 目标是**施法者**
    /// 自己）⇒ 覆盖 A-5 支里全部三个生产者。
    ///
    /// 红检（变异牙）：注释掉 A-5 块里新加的 `magic::spell_in_range(...)` 门 ⇒ ① ② 必红。
    #[test]
    fn spell_cmd_a5_defence_area_blocked_out_of_range() {
        // |Δ| = 15 > MagicAttackRage = 8 ⇒ 过不了门。
        const FAR: u16 = 25;
        for magic_id in [14u16, 15, 31] {
            let (
                mut world,
                caster,
                target,
                online,
                mut saves,
                magic_table,
                mut displays,
                gates,
                mut rx0,
            ) = a5_spell_rig(magic_id, i32::from(FAR), i32::from(FAR));
            let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
                std::collections::HashMap::new();
            ground_sessions.insert("caster".into(), spell_session_ground(caster));
            let catalog = game_svr::ability::StdItemCatalog::new();
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            let rng_before = world.rng.clone();
            let status_before = (world.get_char_status(caster), world.get_char_status(target));
            handle_spell_cmd(
                game_svr::feature::make_long(FAR, FAR),
                magic_id,
                0,
                0,
                "caster",
                911,
                &online,
                &mut world,
                &mut saves,
                &mut ground_sessions,
                &catalog,
                &magic_table,
                &pet_cfg,
                8,
                None,
                &table,
                &mut displays,
                &gates,
                1,
                1,
                2,
            );

            // ① 任何 buff 都不得落（三个生产者对应的三种 buff 全查；目标与施法者都查）。
            for (who, id) in [("target", target), ("caster", caster)] {
                assert!(
                    !world.buffs.has_buff(id, mir2_world::BuffType::DefensePower),
                    "[魔号 {magic_id}] 越界（|Δ|=15 > 8）⇒ {who} 不得获 `DefencePower`（不抽数不施放）"
                );
                assert!(
                    !world
                        .buffs
                        .has_buff(id, mir2_world::BuffType::MagicDefensePower),
                    "[魔号 {magic_id}] 越界 ⇒ {who} 不得获 `MagicDefensePower`"
                );
                assert!(
                    !world.buffs.has_buff(id, mir2_world::BuffType::MagicShield),
                    "[魔号 {magic_id}] 越界 ⇒ {who} 不得获 `MagicShield` buff"
                );
                assert!(
                    !world.entities.get(id).unwrap().magic_shield,
                    "[魔号 {magic_id}] 越界 ⇒ {who} 的 `MagicShield` 不得置位"
                );
            }
            // ② 一个随机数都不抽（oracle `return false` 在任何取数之前）。
            assert_eq!(
                draws_between(&rng_before, &world.rng),
                0,
                "[魔号 {magic_id}] 越界 ⇒ 距离门在取数之前返回 false ⇒ 世界 RNG 零推进"
            );
            // ③ `SM_CHARSTATUSCHANGED(657)` 的**载荷位**（`CharStatus`）不得变：本仓 657 由
            //    `drain_buff_downlink` 读 `TickRecord.buff_status_changes` 出帧，帧体即 `(ActorId, CharStatus)`。
            assert_eq!(
                (world.get_char_status(caster), world.get_char_status(target)),
                status_before,
                "[魔号 {magic_id}] 越界 ⇒ `GetCharStatus()` 不得变（657 的载荷位）"
            );
            // ③b 走一遍**真实出帧面**（世界 tick → `drain_buff_downlink`）⇒ 线上不得出现 657。
            //     阳性对照见 `spell_cmd_a5_defence_area_buff_frame_reaches_wire_in_range`。
            world.tick();
            drain_buff_downlink(
                &world.last_tick,
                &world,
                &mut displays,
                &online,
                &mut ground_sessions,
                &gates,
                12,
            );
            let wire = a5_take_idents(&mut rx0);
            assert!(
                !wire.contains(&mir2_protocol::messages::SM_CHARSTATUSCHANGED),
                "[魔号 {magic_id}] 越界 ⇒ 不得有任何 SM_CHARSTATUSCHANGED(657) 下行帧，实得 {wire:?}"
            );
        }
    }

    /// **片 A-5 夹逼牙 t1（must_fix ①：距离门的**坐标系**，R 级）**——**原始点击点在界内、snap 后越界
    /// ⇒ 必须零抽数、零 buff**。
    ///
    /// 布置：施法者 (10,10)、**点击点 (18,10)**（原始 `|Δx| = 8 <= MagicAttackRage = 8`
    /// ⇒ 用**原始坐标**过门）、**目标实体在 (19,10)**（落在点击点的 1×1 邻域内 ⇒ `CretInNearXy`
    /// 命中 ⇒ snap 成 (19,10) ⇒ `|Δx| = 9 > 8` **越界**）。
    /// oracle `default` 支先 snap（`PlayObject.Attack.cs:1272-1277` **就地改写** `nTargetX/nTargetY`）
    /// 再把改写后的值交给 `DoSpell`（`:1278`）⇒ `MagicManager.cs:155` 的门读的是 **snap 后的坐标**
    /// ⇒ 直接 `return false`：**世界 RNG 抽取数 == 0**、目标/施法者三种 buff 全无。
    ///
    /// 覆盖差异：现有三条用例的点击点恒等于目标实体坐标（snap 是恒等变换）⇒ 覆盖不到本差异；
    /// 本牙的点击点与目标实体坐标**差 1**，正是 `CretInNearXy` 生效的唯一窗口。
    ///
    /// 红检（变异牙）：把 A-5 的门换回**原始坐标** `req.target_x/req.target_y` ⇒ 本牙必红
    /// （`68b0730df` 上实测会抽 3 个数且目标获 buff）。魔号 14/15/31 各跑一遍。
    #[test]
    fn spell_cmd_a5_snap_pushes_click_out_of_range() {
        for magic_id in [14u16, 15, 31] {
            let (
                mut world,
                caster,
                target,
                online,
                mut saves,
                magic_table,
                mut displays,
                gates,
                mut rx0,
            ) = a5_spell_rig(magic_id, 19, 10); // 目标实体在 (19,10)
            let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
                std::collections::HashMap::new();
            ground_sessions.insert("caster".into(), spell_session_ground(caster));
            let catalog = game_svr::ability::StdItemCatalog::new();
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            let rng_before = world.rng.clone();
            handle_spell_cmd(
                game_svr::feature::make_long(18, 10), // 点击点 (18,10)：原始 |Δx|=8 在界
                magic_id,
                u16::try_from(target).unwrap_or(0), // target_actor_id = target ⇒ snap 命中
                0,
                "caster",
                911,
                &online,
                &mut world,
                &mut saves,
                &mut ground_sessions,
                &catalog,
                &magic_table,
                &pet_cfg,
                8,
                None,
                &table,
                &mut displays,
                &gates,
                1,
                1,
                2,
            );
            // ① snap 成 (19,10) ⇒ |Δx| = 9 > 8 ⇒ 距离门在任何取数之前 `return false`。
            assert_eq!(
                draws_between(&rng_before, &world.rng),
                0,
                "[魔号 {magic_id}] snap 后越界（点击 (18,10) → 目标 (19,10)，|Δx|=9 > 8）\
                 ⇒ 距离门在取数前 false ⇒ 世界 RNG 零推进"
            );
            // ② 三种 buff 全无（目标 + 施法者）。
            for (who, id) in [("target", target), ("caster", caster)] {
                assert!(
                    !world.buffs.has_buff(id, mir2_world::BuffType::DefensePower),
                    "[魔号 {magic_id}] snap 后越界 ⇒ {who} 不得获 `DefencePower`"
                );
                assert!(
                    !world
                        .buffs
                        .has_buff(id, mir2_world::BuffType::MagicDefensePower),
                    "[魔号 {magic_id}] snap 后越界 ⇒ {who} 不得获 `MagicDefensePower`"
                );
                assert!(
                    !world.buffs.has_buff(id, mir2_world::BuffType::MagicShield),
                    "[魔号 {magic_id}] snap 后越界 ⇒ {who} 不得获 `MagicShield` buff"
                );
                assert!(
                    !world.entities.get(id).unwrap().magic_shield,
                    "[魔号 {magic_id}] snap 后越界 ⇒ {who} 的 `MagicShield` 不得置位"
                );
            }
            let _ = a5_take_idents(&mut rx0);
        }
    }

    /// **片 A-5 夹逼牙 t2（must_fix ① 的另一侧）**——**原始点击点越界、snap 后在界 ⇒ 必须施放**。
    ///
    /// 布置：施法者 (10,10)、**点击点 (19,10)**（原始 `|Δx| = 9 > 8` ⇒ 用原始坐标**过不了门**）、
    /// **目标实体在 (18,10)**（邻域内 ⇒ snap 成 (18,10) ⇒ `|Δx| = 8 <= 8` **在界**）
    /// ⇒ oracle 的 `DoSpell` 照常施放。
    ///
    /// 断言：① `draws > 0`（生产链确实走到取数）；② 目标/施法者获得对应 buff
    /// （14 ⇒ 目标 `MagicDefensePower`；15 ⇒ 目标 `DefensePower`；31 ⇒ 施法者 `MagicShield`）。
    ///
    /// 红检（变异牙）：换回**原始坐标** ⇒ 本牙必红（原始 |Δx|=9 越界 ⇒ 零抽数、零 buff）。
    #[test]
    fn spell_cmd_a5_snap_pulls_click_into_range() {
        for magic_id in [14u16, 15, 31] {
            let (
                mut world,
                caster,
                target,
                online,
                mut saves,
                magic_table,
                mut displays,
                gates,
                mut rx0,
            ) = a5_spell_rig(magic_id, 18, 10); // 目标实体在 (18,10)
            let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
                std::collections::HashMap::new();
            // **牙的布置修正（P2，设计件 §7-10）**：14/15 补 `CheckAmulet(1,1)` 后，夹具必须同时有
            // `ArmRingl` 槽与 catalog 模板（`index=1`、`std_mode=25`、`shape=5`、`dura=600`）。
            ground_sessions.insert("caster".into(), a5_session_with_amulet(caster, 600));
            let catalog = a5_amulet_catalog();
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            let rng_before = world.rng.clone();
            handle_spell_cmd(
                game_svr::feature::make_long(19, 10), // 点击点 (19,10)：原始 |Δx|=9 越界
                magic_id,
                u16::try_from(target).unwrap_or(0), // target_actor_id = target ⇒ snap 命中
                0,
                "caster",
                911,
                &online,
                &mut world,
                &mut saves,
                &mut ground_sessions,
                &catalog,
                &magic_table,
                &pet_cfg,
                8,
                None,
                &table,
                &mut displays,
                &gates,
                1,
                1,
                2,
            );
            assert!(
                draws_between(&rng_before, &world.rng) > 0,
                "[魔号 {magic_id}] snap 后在界（点击 (19,10) → 目标 (18,10)，|Δx|=8 ≤ 8）\
                 ⇒ 生产链必须走到取数（世界 RNG 前进）"
            );
            match magic_id {
                31 => assert!(
                    world
                        .buffs
                        .has_buff(caster, mir2_world::BuffType::MagicShield),
                    "snap 后在界 ⇒ 施法者获 `MagicShield`（技能 31 作用于自身）"
                ),
                14 => assert!(
                    world
                        .buffs
                        .has_buff(target, mir2_world::BuffType::MagicDefensePower),
                    "snap 后在界 ⇒ 目标获 `MagicDefensePower`（技能 14 → `MagDefenceUp`）"
                ),
                _ => assert!(
                    world
                        .buffs
                        .has_buff(target, mir2_world::BuffType::DefensePower),
                    "snap 后在界 ⇒ 目标获 `DefencePower`（技能 15 → `DefenceUp`）"
                ),
            }
            let _ = a5_take_idents(&mut rx0);
        }
    }

    /// 片 `openmir2-snap-cell-fidelity` 两条牙共用的一次施法（走**生产入口** `handle_spell_cmd`）。
    ///
    /// `mask = Some((mx,my))` 时先把该格掩码（`MapGrid::set_map_xy_flag(mx, my, false)`
    /// ⇒ `CellAttribute::LowWall`，生产侧唯一写掩码的口是 `crates/world/src/castle.rs:591`
    /// `apply_structure_events` 的城门/城墙 `SetMapXyFlag`）——被掩码格
    /// `MapCellInfo::valid() == false` ⇒ `get_cell_info` 返回 `success=false` ⇒ oracle
    /// `CretInNearXy` 的 `if (cellSuccess && cellInfo.IsAvailable)` 跳过该格。
    ///
    /// 返回 `(世界 RNG 推进步数, 施法者 MagicShield, 目标 DefencePower/MagDefencePower)`。
    #[allow(clippy::type_complexity)]
    fn snap_fidelity_cast(
        magic_id: u16,
        target_x: i32,
        target_y: i32,
        click: (u16, u16),
        mask: Option<(i32, i32)>,
    ) -> (usize, bool, bool) {
        let (
            mut world,
            caster,
            target,
            online,
            mut saves,
            magic_table,
            mut displays,
            gates,
            mut rx0,
        ) = a5_spell_rig(magic_id, target_x, target_y);
        if let Some((mx, my)) = mask {
            assert!(
                world.maps[0].set_map_xy_flag(mx, my, false),
                "掩码格 ({mx},{my}) 须在界且当前 Valid（否则该格不会被置成 LowWall）"
            );
        }
        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        // **牙的布置修正（P2，设计件 §7-10）**：14/15 补 `CheckAmulet(1,1)` 后，夹具必须同时有
        // `ArmRingl` 槽与 catalog 模板（`index=1`、`std_mode=25`、`shape=5`、`dura=600`）；
        // 只加槽不加模板 ⇒ `amulet_slot` 返回 None ⇒ 门不过。
        ground_sessions.insert("caster".into(), a5_session_with_amulet(caster, 600));
        let catalog = a5_amulet_catalog();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        let rng_before = world.rng.clone();
        handle_spell_cmd(
            game_svr::feature::make_long(click.0, click.1),
            magic_id,
            u16::try_from(target).unwrap_or(0),
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            None,
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        let _ = a5_take_idents(&mut rx0);
        (
            draws_between(&rng_before, &world.rng),
            world
                .buffs
                .has_buff(caster, mir2_world::BuffType::MagicShield),
            world
                .buffs
                .has_buff(target, mir2_world::BuffType::DefensePower)
                || world
                    .buffs
                    .has_buff(target, mir2_world::BuffType::MagicDefensePower),
        )
    }

    /// **片 `openmir2-snap-cell-fidelity` 本体牙（格不可用 ⇒ 不 snap，tier=R）**：
    /// 目标**在点击点的 1×1 窗口内**，但它站的格**被掩码**（不可用）⇒ oracle `CretInNearXy`
    /// 逐格扫时跳过该格 ⇒ **不** snap ⇒ `tx/ty` 保持原始点击坐标 ⇒ 用 (18,10) 过门
    /// （`|Δx| = 8 <= MagicAttackRage = 8`）⇒ **照常施放**。
    ///
    /// 布置：施法者 (10,10)、点击 **(18,10)**、目标实体 **(19,10)**（`|Δx| = 1 <= 1`，行内
    /// 「实体坐标 ±1 比较」会 snap）、格 (19,10) 置 `LowWall`。
    ///
    /// **本片修复前后**：行内实现会 snap 成 (19,10) ⇒ `|Δx| = 9 > 8` ⇒ 距离门零抽数、零施放；
    /// 忠实镜像（[`queryuser::cetin_near_xy`]）不 snap ⇒ 抽数 > 0、技能 31 的 `MagicShield` 落地。
    ///
    /// 断言：① 世界 RNG **必须前进**（走到 `power_*` 取数）；② 技能 31 ⇒ 施法者获 `MagicShield`；
    /// ③ 技能 14/15 ⇒ 目标**不得**获 buff——oracle `MagMakeDefenceArea` 的已知 bug 只对
    /// **中心格** `(nX,nY) = 点击格 (18,10)` 施加（`crates/world/src/world.rs:671` 逐行复刻），
    /// 目标在 (19,10) ⇒ 中心格无人 ⇒ 零命中（这一条同时钉住「不 snap」本身：若坐标被改成目标格，
    /// 目标就会获 buff ⇒ 断言 ③ 必红）。
    ///
    /// 红检（变异牙，实测见补丁说明）：把 [`spell_snap_target`] 里的 `cetin_near_xy` 换回行内
    /// 「实体坐标 ±1 比较」⇒ ① 必红（零抽数）、② 必红；牙 b 仍绿（两条牙各司其职）。
    #[test]
    fn spell_cmd_snap_masked_cell_does_not_snap() {
        for magic_id in [31u16, 15, 14] {
            let (draws, shield, defence) =
                snap_fidelity_cast(magic_id, 19, 10, (18, 10), Some((19, 10)));
            assert!(
                draws > 0,
                "[魔号 {magic_id}] 目标站在**被掩码**的格 (19,10) 上 ⇒ `CretInNearXy` 跳过该格                  ⇒ 不 snap ⇒ 原始 (18,10) 过门（|Δx|=8 ≤ 8）⇒ 世界 RNG 必须前进"
            );
            if magic_id == 31 {
                assert!(
                    shield,
                    "不 snap ⇒ 在界 ⇒ 技能 31 `MagBubbleDefenceUp` 作用于施法者自身 ⇒ MagicShield 落地"
                );
            } else {
                assert!(
                    !defence,
                    "[魔号 {magic_id}] 不 snap ⇒ `MagMakeDefenceArea` 的中心格 = 点击格 (18,10)                      （无人）⇒ 目标 (19,10) 不得获任何防御系 buff"
                );
            }
        }
    }

    /// **片 `openmir2-snap-cell-fidelity` 牙 b（窗口宽度上界，tier=R）**：目标在点击点
    /// **2 格**外（`|Δx| = 2`）⇒ `CretInNearXy` 的 3×3 窗口**不含**它 ⇒ **不** snap
    /// ⇒ `tx/ty` = 原始点击 (18,10)（`|Δx| = 8 <= 8`）⇒ 照常施放。
    ///
    /// 与本体牙的分工：本体牙钉「格不可用 ⇒ 不 snap」（同一窗口内的目标），本牙钉「**窗口上界 = ±1**」
    /// （可用的格、但坐标超出窗口）。下界（±0 时必红）已由 `spell_cmd_a5_snap_pushes_click_out_of_range`
    /// / `spell_cmd_a5_snap_pulls_click_into_range` 覆盖。
    ///
    /// 断言：① 世界 RNG **必须前进**；② 技能 31 ⇒ 施法者获 `MagicShield`；③ 技能 14/15 ⇒ 目标无 buff
    /// （同本体牙 ③ 的口径）。
    ///
    /// 红检（变异牙，实测见补丁说明）：把 [`queryuser::cetin_near_xy`] 的 `(x-1)..=(x+1)` 改成
    /// `(x-2)..=(x+2)`（窗口 ±2）⇒ snap 到 (20,10) ⇒ `|Δx| = 10 > 8` ⇒ 零抽数 ⇒ ① 必红。
    #[test]
    fn spell_cmd_snap_window_width_upper_bound() {
        for magic_id in [31u16, 15, 14] {
            let (draws, shield, defence) = snap_fidelity_cast(magic_id, 20, 10, (18, 10), None);
            assert!(
                draws > 0,
                "[魔号 {magic_id}] 目标在点击点 (18,10) 的 ±2 格 ⇒ 出 3×3 窗口 ⇒ 不 snap                  ⇒ 原始坐标过门（|Δx|=8 ≤ 8）⇒ 世界 RNG 必须前进（窗口若被改成 ±2 则必红）"
            );
            if magic_id == 31 {
                assert!(
                    shield,
                    "不 snap ⇒ 在界 ⇒ 技能 31 `MagBubbleDefenceUp` 作用于施法者自身 ⇒ MagicShield 落地"
                );
            } else {
                assert!(
                    !defence,
                    "[魔号 {magic_id}] 不 snap ⇒ 中心格 = 点击格 (18,10)（无人）                     ⇒ 目标 (20,10) 不得获任何防御系 buff"
                );
            }
        }
    }

    /// **对照牙（越界那条 ③b 的阳性对照）**：同一布置 + in-range ⇒ 加完 buff 后把 buff 递减到
    /// **到期**（`StateTick → 0` 触发 `Operate` 的 `boChg`）⇒ `TickRecord.buff_status_changes` 非空
    /// ⇒ `drain_buff_downlink` **确实**在线上发出 `SM_CHARSTATUSCHANGED(657)`。
    ///
    /// 作用：证明越界用例里「零 657」不是「drain 面根本不工作」造成的假绿。
    #[test]
    fn spell_cmd_a5_defence_area_buff_frame_reaches_wire_in_range() {
        let (
            mut world,
            caster,
            target,
            online,
            mut saves,
            magic_table,
            mut displays,
            gates,
            mut rx0,
        ) = a5_spell_rig(15, 12, 12);
        let mut ground_sessions: std::collections::HashMap<String, SessionGround> =
            std::collections::HashMap::new();
        // **牙的布置修正（P2，设计件 §7-10）**：14/15 补 `CheckAmulet(1,1)` 后，夹具必须同时有
        // `ArmRingl` 槽与 catalog 模板（`index=1`、`std_mode=25`、`shape=5`、`dura=600`）；
        // 只加槽不加模板 ⇒ `amulet_slot` 返回 None ⇒ 门不过。
        ground_sessions.insert("caster".into(), a5_session_with_amulet(caster, 600));
        let catalog = a5_amulet_catalog();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let table = game_svr::mongen::MonsterTable::new(Vec::new());
        handle_spell_cmd(
            game_svr::feature::make_long(12, 12),
            15,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            None,
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );
        assert!(
            world
                .buffs
                .has_buff(target, mir2_world::BuffType::DefensePower),
            "前置：in-range ⇒ 目标已获 `DefencePower`"
        );
        let _ = a5_take_idents(&mut rx0);
        // 推到 buff 到期（`Operate` 的 `d.state_tick == 0` 支 ⇒ `bo_chg`）。
        let mut seen = false;
        for _ in 0..400 {
            world.clock_ms += mir2_world::BUFF_STATE_TICK_GATE_MS;
            world.tick();
            drain_buff_downlink(
                &world.last_tick,
                &world,
                &mut displays,
                &online,
                &mut ground_sessions,
                &gates,
                12,
            );
            if a5_take_idents(&mut rx0).contains(&mir2_protocol::messages::SM_CHARSTATUSCHANGED) {
                seen = true;
                break;
            }
        }
        assert!(
            seen,
            "阳性对照：in-range 加了 buff 后递减到期 ⇒ drain 面**确实**发 657 \
             （证明越界用例的「零 657」是真绿，不是 drain 不工作）"
        );
    }
    /// **`openmir2-m3-pet-slave-summon`（第②片）**：`CM_SPELL(17 召唤骷髅)` 效果体接线——
    /// 护身符门过 ⇒ 扣耐久 + 自身 `SM_DURACHANGE`；对观察者广播 `SM_SPELL`/`SM_MAGICFIRE`；
    /// 自身收 `+GD`。空怪表 ⇒ 造怪失败，但仍走完帧面（oracle `ClientSpellXY` 恒 `result=true`）。
    ///
    /// 红检：① `cast_slave_spell` 不消耗护身符（`use_amulet` 不改耐久）⇒ 耐久仍 450 必红；
    /// ② 把 `sm_spell` 的 `Series` 换成 `MagicId`（不取 `Magic.Effect`）⇒ 帧字段断言必红；
    /// ③ 不广播 `RM_SPELL`（去掉 `broadcast_ref_msg`）⇒ 观察者无 `SM_SPELL` 必红。
    #[test]
    fn spell_cmd_summon_wires_amulet_and_frames() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let caster = {
            let mut e = new_player_entity("caster".to_string(), 10, 10);
            e.level = 40;
            world.add_entity(e)
        };
        let observer = world.add_entity(new_player_entity("obs".to_string(), 11, 10));
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            caster,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
        );
        displays.set(
            observer,
            downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"obs".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "uo".into(),
                chr_name: "obs".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 912,
                actor_id: observer,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: 17,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = spell_session_ground(caster);
        sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
            make_index: 1,
            index: 1,
            dura: 450,
            dura_max: 1000,
            desc: [0; 14],
        });
        ground_sessions.insert("caster".into(), sg);
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "护身符".into(),
                std_mode: 25,
                shape: 5,
                ..mir2_data::StdItem::default()
            },
        );
        let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id: 17,
            effect: 3,
            effect_type: 4,
            train_lv: 3,
            ..mir2_data::MagicInfo::default()
        }]);
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let registry = mir2_envir::MapRegistry::from_entries(
            mir2_envir::MapLoader::new(".", "map", "envir"),
            Vec::new(),
        );
        let table = game_svr::mongen::MonsterTable::new(Vec::new());

        handle_spell_cmd(
            game_svr::feature::make_long(10, 11),
            17,
            9999,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            Some(&registry),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );

        let mut frames: Vec<(i32, Vec<u8>)> = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            match m {
                SimToGate::SendFrame { socket, body } => frames.push((socket, body)),
                SimToGate::SendRaw { socket, payload } => frames.push((socket, payload)),
                other => panic!("意外的下行：{other:?}"),
            }
        }
        let ident_of = |b: &[u8]| {
            mir2_protocol::frame::CommandMessage::from_bytes(b)
                .unwrap()
                .ident
        };
        let obs: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|(s, _)| *s == 912)
            .map(|(_, b)| b)
            .collect();
        assert!(
            obs.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_SPELL),
            "观察者应收 SM_SPELL(RM_SPELL)；实得 {obs:?}"
        );
        assert!(
            obs.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_MAGICFIRE),
            "观察者应收 SM_MAGICFIRE；实得 {obs:?}"
        );
        let me: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|(s, _)| *s == 911)
            .map(|(_, b)| b)
            .collect();
        assert!(
            me.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_DURACHANGE),
            "施法者自身应收 SM_DURACHANGE；实得 {me:?}"
        );
        // **F-1（reviewer-6 `7724b9e441`）**：`RM_MAGICFIRE` 的 oracle 处理器无
        // `ActorId != ActorId` 守卫（`PlayObject.Message.cs:1788-1793`）⇒ 施法者自己也应收
        // `SM_MAGICFIRE`；而 `RM_SPELL`（有守卫）不给自己发（这里 `me` 不含 `SM_SPELL`）。
        assert!(
            me.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_MAGICFIRE),
            "F-1：施法者自身应收 SM_MAGICFIRE（RM_MAGICFIRE 无自身守卫）；实得 {me:?}"
        );
        assert!(
            !me.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_SPELL),
            "RM_SPELL 有 `ActorId != ActorId` 守卫 ⇒ 施法者自身不应收 SM_SPELL；实得 {me:?}"
        );
        assert!(me.iter().any(|b| b.starts_with(b"+GD/")), "成功支仍回 +GD");
        // 护身符扣至 350（450 - 1*100）。
        assert_eq!(
            ground_sessions["caster"].use_items[game_svr::ability::SLOT_ARMRING_L]
                .as_ref()
                .unwrap()
                .dura,
            350,
            "UseAmulet 扣耐久落 UseItems"
        );
    }

    /// **⑨-2 护身符扣光帧面**：`UseAmulet` 的 `else` 支（`MagicBase.cs:121-126`）——耐久恰为
    /// `nCount*100` 时 oracle 走 `Dura = 0; SendDelItems(item); Index = 0;`，宿主须发**立即**
    /// `SM_DELITEM(202)`（`PlayObject.Base.cs:1648-1665`），且帧内 `Dura` = 0、清槽。
    ///
    /// 红检：① 删掉清槽前取件/发帧（回到登记前的 header-only 无帧）⇒ 无 `SM_DELITEM` 必红；
    /// ② 帧内 `Dura` 用扣光前的值（不做 `Dura=0`）⇒ 尾字节不等必红。
    #[test]
    fn spell_cmd_summon_exhausted_amulet_emits_delitem() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let caster = {
            let mut e = new_player_entity("caster".to_string(), 10, 10);
            e.level = 40;
            world.add_entity(e)
        };
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            caster,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: 17,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = spell_session_ground(caster);
        // 17 的护身符需求 = `CheckAmulet(1,1)`：`round(Dura/100) >= 1` ⇒ Dura=100 过门，
        // 且 `Dura > 100` 为假 ⇒ 走 else（扣光删除）支。
        sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
            make_index: 1,
            index: 1,
            dura: 100,
            dura_max: 1000,
            desc: [0; 14],
        });
        ground_sessions.insert("caster".into(), sg);
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        let amulet_tpl = mir2_data::StdItem {
            name: "护身符".into(),
            std_mode: 25,
            shape: 5,
            ..mir2_data::StdItem::default()
        };
        catalog.insert(1, amulet_tpl.clone());
        let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id: 17,
            effect: 3,
            effect_type: 4,
            train_lv: 3,
            ..mir2_data::MagicInfo::default()
        }]);
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let registry = mir2_envir::MapRegistry::from_entries(
            mir2_envir::MapLoader::new(".", "map", "envir"),
            Vec::new(),
        );
        let table = game_svr::mongen::MonsterTable::new(Vec::new());

        handle_spell_cmd(
            game_svr::feature::make_long(10, 11),
            17,
            9999,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            Some(&registry),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );

        let mut frames: Vec<(i32, Vec<u8>)> = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            match m {
                SimToGate::SendFrame { socket, body } => frames.push((socket, body)),
                SimToGate::SendRaw { socket, payload } => frames.push((socket, payload)),
                other => panic!("意外的下行：{other:?}"),
            }
        }
        let ident_of = |b: &[u8]| {
            mir2_protocol::frame::CommandMessage::from_bytes(b)
                .unwrap()
                .ident
        };
        let me: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|(s, _)| *s == 911)
            .map(|(_, b)| b)
            .collect();
        let del = me
            .iter()
            .find(|b| ident_of(b) == mir2_protocol::messages::SM_DELITEM)
            .unwrap_or_else(|| panic!("扣光支应发 SM_DELITEM；实得 {me:?}"));
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(del).unwrap();
        assert_eq!(cm.recog, caster, "Recog=ActorId");
        assert_eq!((cm.param, cm.tag, cm.series), (0, 0, 1), "Series=1");
        // 尾 = `EncodeBuffer(clientItem)`：`Dura` 恒 0（oracle 先置 0 再 `SendDelItems`）。
        let expect_ci = game_svr::itemwire::ClientItem {
            tpl: &amulet_tpl,
            name: "护身符".into(),
            make_index: 1,
            dura: 0,
            dura_max: 1000,
            desc: [0; 14],
        };
        let expect_tail =
            mir2_protocol::edcode::encode(&game_svr::itemwire::encode_client_item(&expect_ci));
        assert_eq!(
            mir2_protocol::edcode::decode(&del[12..]),
            mir2_protocol::edcode::decode(&expect_tail),
            "SM_DELITEM 尾 = EncodeBuffer(ClientItem，Dura=0)"
        );
        assert!(
            !me.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_DURACHANGE),
            "扣光支不发 SM_DURACHANGE（oracle 只发 SendDelItems）；实得 {me:?}"
        );
        assert!(
            ground_sessions["caster"].use_items[game_svr::ability::SLOT_ARMRING_L].is_none(),
            "扣光支清槽（UseItems[idx] = None）"
        );
    }

    /// **⑨-2 残余（46 分身）**：`CM_SPELL(46)` 效果体接线——造玩家型克隆体（名字 `Clone`、
    /// 坐标=主人、`Dir = GetBackDir(主人转向后的 Dir)`、格被占、不入 `SlaveList`）+ 展示表登记
    /// + 主人/观察者收 `SM_TURN`（名尾 `"Clone/255"`）与 `SM_MAGICFIRE`，观察者收 `SM_SPELL`。
    ///
    /// 红检：① `dir` 用主人正向（不用 `GetBackDir`）⇒ 展示/帧方向断言必红；
    /// ② 不发克隆体 `sm_turn` ⇒ `SM_TURN`/名尾断言必红；③ 不造实体 ⇒ 实体/格占用断言必红。
    #[test]
    fn spell_cmd_clone_wires_entity_and_frames() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let caster = {
            let mut e = new_player_entity("caster".to_string(), 10, 10);
            e.level = 40;
            world.add_entity(e)
        };
        let observer = world.add_entity(new_player_entity("obs".to_string(), 11, 10));
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        // 主人 feature：gender=1、hair=5（dress/weapon 故意非 0，副本应丢掉）。
        displays.set(
            caster,
            downlink::ActorDisplay::new(
                4,
                0,
                game_svr::feature::make_human_feature(0, 3 * 2 + 1, 1 + 2 * 2, 5 * 2 + 1),
                0,
                0,
                downlink::PLAYER_NAME_COLOR,
                b"caster".to_vec(),
            ),
        );
        displays.set(
            observer,
            downlink::ActorDisplay::new(4, 0, 112, 0, 0, 255, b"obs".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uc".into(),
                chr_name: "caster".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 911,
                actor_id: caster,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "uo".into(),
                chr_name: "obs".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 912,
                actor_id: observer,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        let mut record = stage6_record();
        record.data.magic = Some(vec![Some(record::MagicRcd {
            mag_idx: 46,
            level: 1,
            magic_key: u16::from(b'm'),
            tran_point: 0,
        })]);
        saves.insert(
            "caster".into(),
            SavedHuman {
                account: "uc".into(),
                record,
                enter_map: "0".into(),
            },
        );
        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        // 真客户端会话（`SoftVersionDateEx != 0`）⇒ 版本门「双 0」子句不成立，46 正常施放。
        ground_sessions.insert("caster".into(), spell_session_ground(caster));
        let catalog = game_svr::ability::StdItemCatalog::new();
        let magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id: 46,
            effect: 1,
            effect_type: 1,
            train_lv: 3,
            ..mir2_data::MagicInfo::default()
        }]);
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let registry: Option<mir2_envir::MapRegistry> = None;
        let table = game_svr::mongen::MonsterTable::new(Vec::new());

        handle_spell_cmd(
            // 目标在右 ⇒ `default` 支把主人 Dir 转向右(2)；克隆体 `Dir = GetBackDir(2) = 6`。
            game_svr::feature::make_long(12, 10),
            46,
            0,
            0,
            "caster",
            911,
            &online,
            &mut world,
            &mut saves,
            &mut ground_sessions,
            &catalog,
            &magic_table,
            &pet_cfg,
            8,
            registry.as_ref(),
            &table,
            &mut displays,
            &gates,
            1,
            1,
            2,
        );

        let (clone_id, cx, cy, cray, cslaves) = {
            let c = world
                .entities
                .iter()
                .find(|e| e.name == mir2_world::CLONE_NAME)
                .expect("应造出克隆体实体");
            (c.id, c.x, c.y, c.race, c.slave_list.len())
        };
        assert_eq!((cx, cy), (10, 10), "坐标 = 主人坐标");
        assert_eq!(cray, mir2_world::ACTOR_RACE_PLAY, "玩家型克隆体");
        assert_eq!(cslaves, 0, "克隆体不入 SlaveList");
        assert!(
            world.entities.get(caster).unwrap().slave_list.is_empty(),
            "主人的 SlaveList 不被触碰"
        );
        // 展示：`Dir = GetBackDir(主人转向后的 Dir=2) = 6`；feature 取主人 Gender/Hair（1/5）。
        let d = displays.get(clone_id).expect("克隆体展示应登记");
        assert_eq!(d.dir, 6, "Dir = GetBackDir(右=2) = 左=6");
        assert_eq!(d.show_name, downlink::gbk("Clone"));
        assert_eq!(d.name_color, downlink::PLAYER_NAME_COLOR);
        assert_eq!(
            d.feature,
            game_svr::feature::make_human_feature(0, 1, 1, 5 * 2 + 1),
            "Gender/Hair 照抄、Dress/Weapon 归 0"
        );
        // 格占用。
        let (cell, ok) = world.maps[0].get_cell_info(10, 10);
        assert!(ok);
        assert!(
            cell.obj_list
                .iter()
                .any(|o| o.cell_obj_id == clone_id && o.actor_object),
            "克隆体应占主人同格"
        );

        let mut frames: Vec<(i32, Vec<u8>)> = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            match m {
                SimToGate::SendFrame { socket, body } => frames.push((socket, body)),
                SimToGate::SendRaw { socket, payload } => frames.push((socket, payload)),
                other => panic!("意外的下行：{other:?}"),
            }
        }
        let ident_of = |b: &[u8]| {
            mir2_protocol::frame::CommandMessage::from_bytes(b)
                .unwrap()
                .ident
        };
        let obs: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|(s, _)| *s == 912)
            .map(|(_, b)| b)
            .collect();
        let me: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|(s, _)| *s == 911)
            .map(|(_, b)| b)
            .collect();
        assert!(
            obs.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_SPELL),
            "观察者应收 SM_SPELL(46)；实得 {obs:?}"
        );
        assert!(
            obs.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_MAGICFIRE),
            "观察者应收 SM_MAGICFIRE"
        );
        assert!(
            me.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_MAGICFIRE),
            "F-1：主人自己也收 SM_MAGICFIRE；实得 {me:?}"
        );
        assert!(
            !me.iter()
                .any(|b| ident_of(b) == mir2_protocol::messages::SM_SPELL),
            "RM_SPELL 有自身守卫 ⇒ 主人自己不应收 SM_SPELL"
        );
        // `SM_TURN`（Recog = 克隆体 id）+ 名尾 `"Clone/255"`；两个在线玩家各一。
        let turns: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|(_, b)| ident_of(b) == mir2_protocol::messages::SM_TURN)
            .map(|(_, b)| b)
            .collect();
        assert_eq!(turns.len(), 2, "主人与观察者各一（克隆体自己被排除）");
        for t in &turns {
            assert_eq!(
                i32::from_le_bytes([t[0], t[1], t[2], t[3]]),
                clone_id,
                "SM_TURN Recog = 克隆体 ActorId"
            );
            let msg = mir2_protocol::edcode::decode(&t[23..]);
            assert!(
                msg.starts_with(b"Clone/"),
                "名尾应为 Clone/<color>；实得 {msg:?}"
            );
        }
        assert!(me.iter().any(|b| b.starts_with(b"+GD/")), "成功支回 +GD");
        // 熟练度尾：`level=1 < 3` 且 `boTrain=true` ⇒ 若升级门过则 `TrainSkill(Random(3)+1)` 已落。
        assert_eq!(
            saves["caster"].record.data.magic.as_ref().unwrap()[0]
                .as_ref()
                .unwrap()
                .mag_idx,
            46
        );
    }

    /// **第一片（战斗下行）**：手造一个 tick 记录 ⇒ `drain_combat_downlink` 给受击玩家自己发
    /// `SM_STRUCK`（生产默认 = 冻结客户端 `HIGHHP` 布局：头 `LoWord(HP)/HiWord(HP)/伤害` +
    /// 16B `MessageBodyWL` 尾 `{Param1=MaxHP,Param2=status,Tag1=hitter,Tag2=mag}`；
    /// `MIR2_CLIENT_ABILITY_LAYOUT=0` ⇒ oracle 布局 `{Param1=feature}`）、给同屏（含死者自己）发
    /// `SM_NOWDEATH`（头 `X/Y/Dir` + 8B `CharDesc` 尾），并把世界实体 HP 同步回会话 `WAbil.HP`。
    ///
    /// 红检：① 把 `smframe::sm_struck_client` 的头 `hp` 拆位（`lo_word`/`hi_word` 互换）⇒ 客户端布局头断言必红；
    /// ② 把死亡广播改成 `broadcast_ref_msg`（排除自己）⇒ 死者自己收不到 `SM_NOWDEATH` 必红；
    /// ③ 把 `smframe::sm_struck_client` 的尾 `Param1` 改回 `feature` ⇒ `struck[12..]` 尾断言必红
    ///   （**M-1 收口**：本用例现在真的逐字节断言 16B `MessageBodyWL` 尾，不再只声称覆盖）。
    #[test]
    fn combat_downlink_sends_struck_and_nowdeath() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let victim = {
            let mut e = mir2_world::Entity::new(0, "victim".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let attacker = {
            let mut e = mir2_world::Entity::new(0, "atk".to_string(), 11, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            victim,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"victim".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uv".into(),
                chr_name: "victim".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: victim,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("victim".into(), test_session_ground(victim));

        let rec = mir2_world::TickRecord {
            attacks: vec![(
                attacker,
                victim,
                mir2_world::AttackOutcome {
                    power: 10,
                    hit: true,
                    damage: 7,
                    killed: true,
                    target_hp_after: 0,
                },
            )],
            deaths: vec![(victim, 0, 0, None, 0)],
            ..Default::default()
        };
        drain_combat_downlink(&rec, &world, &displays, &online, &mut sessions, &gates);
        let mut bodies = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { socket, body } = m {
                assert_eq!(socket, 901);
                bodies.push(body);
            }
        }
        assert_eq!(bodies.len(), 2, "先受击后死亡两帧");
        let struck = &bodies[0];
        assert_eq!(
            u16::from_le_bytes([struck[4], struck[5]]),
            mir2_protocol::messages::SM_STRUCK,
            "第一帧 = SM_STRUCK"
        );
        let cm = CommandMessage::from_bytes(struck).expect("12B");
        // 生产默认 = 冻结客户端 `HIGHHP` 布局（`sm_struck_frame` ⇒ `sm_struck_client`）：
        // `param/tag` 拆 32 位 HP、`MaxHP` 在尾 `Param1`。`MIR2_CLIENT_ABILITY_LAYOUT=0` ⇒ oracle 布局。
        if game_svr::smframe::client_layout_enabled() {
            assert_eq!(
                (cm.recog, cm.param, cm.tag, cm.series),
                (victim, 0, 0, 7),
                "SM_STRUCK(客户端布局) 头 = (受击者, LoWord(HP), HiWord(HP), 伤害)"
            );
        } else {
            assert_eq!(
                (cm.recog, cm.param, cm.tag, cm.series),
                (victim, 0, 100, 7),
                "SM_STRUCK(oracle) 头 = (受击者, HP, MaxHP, 伤害)"
            );
        }
        // **M-1 收口**（reviewer-5 `ebfd15a8`）：文档声称覆盖 16B `MessageBodyWL` 尾，这里真的
        // 逐字节断言 `struck[12..]`，否则尾 mutation 抓不到。
        // 尾 = Encode(MessageBodyWL{ Param1=?, Param2=CharStatus,
        //                            Tag1=命中者 ActorId, Tag2=(RM_STRUCK_MAG ? 1 : 0) })。
        // `Param1`：客户端布局 = `MaxHP`（HIGHHP 支读这个）；oracle = `GetFeature()`。
        let param1 = if game_svr::smframe::client_layout_enabled() {
            100_i32 // MaxHP
        } else {
            111_i32 // GetFeature()
        };
        let mut wl = [0u8; 16];
        wl[0..4].copy_from_slice(&param1.to_le_bytes()); // Param1
        wl[4..8].copy_from_slice(&0_i32.to_le_bytes()); // Param2 = CharStatus
        wl[8..12].copy_from_slice(&attacker.to_le_bytes()); // Tag1 = 命中者 ActorId
        wl[12..16].copy_from_slice(&0_i32.to_le_bytes()); // Tag2 = (RM_STRUCK_MAG ? 1 : 0)
        assert_eq!(
            &struck[12..],
            &mir2_protocol::edcode::encode(&wl),
            "SM_STRUCK 尾 = Encode(MessageBodyWL{{Param1=MaxHP(client)|feature(oracle),Param2=status,Tag1=hitter,Tag2=mag}})"
        );
        assert_eq!(
            sessions["victim"].state.wabil.hp, 0,
            "受击后世界 HP 同步回会话 WAbil"
        );
        let death = &bodies[1];
        assert_eq!(
            u16::from_le_bytes([death[4], death[5]]),
            mir2_protocol::messages::SM_NOWDEATH,
            "第二帧 = SM_NOWDEATH（nParam3==1）"
        );
        let cm = CommandMessage::from_bytes(death).expect("12B");
        assert_eq!((cm.recog, cm.param, cm.tag, cm.series), (victim, 10, 10, 4));
        assert_eq!(
            &death[12..],
            &mir2_protocol::edcode::encode(&downlink::char_desc(111, 0)),
            "死亡尾 = Encode(8B CharDesc)"
        );
    }

    /// **片㉜（③ DoD③「屏幕见怪并能攻击造成伤害」）**：受击帧按 oracle `SendRefMsg(RM_STRUCK)`
    /// 广播给**受击者视野内全体 `Play`**（含受害者自己），不再只发受害者一人。
    ///
    /// 锚点：`BaseObject.Attack.cs:57` → `BaseObject.Base.cs:699-705` →
    /// `BaseObject.Message.cs:383+`（`Race==Play` 且切比雪夫 ≤ `SendRefMsgRange`=12）→
    /// `PlayObject.Message.cs:1562-1628`。
    ///
    /// 红检：把 `drain_combat_downlink` ① 的广播循环改回「只发受击者自己」（旧实现）⇒
    /// 本用例必红（观察者 902 收不到 `SM_STRUCK`）。
    #[test]
    fn combat_downlink_broadcasts_struck_to_all_visible_players() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let victim = {
            let mut e = mir2_world::Entity::new(0, "victim".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let attacker = {
            let mut e = mir2_world::Entity::new(0, "atk".to_string(), 11, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let observer = {
            let mut e = mir2_world::Entity::new(0, "obs".to_string(), 21, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            victim,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"victim".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uv".into(),
                chr_name: "victim".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: victim,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "uo".into(),
                chr_name: "obs".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 902,
                actor_id: observer,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("victim".into(), test_session_ground(victim));

        let rec = mir2_world::TickRecord {
            attacks: vec![(
                attacker,
                victim,
                mir2_world::AttackOutcome {
                    power: 10,
                    hit: true,
                    damage: 7,
                    killed: false,
                    target_hp_after: 12,
                },
            )],
            ..Default::default()
        };
        drain_combat_downlink(&rec, &world, &displays, &online, &mut sessions, &gates);
        let mut per_socket: HashMap<i32, Vec<u8>> = HashMap::new();
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { socket, body } = m {
                per_socket.insert(socket, body);
            }
        }
        assert_eq!(
            per_socket.len(),
            2,
            "受击帧必须广播给同图视野内全体在线玩家（受害者 + 观察者）：{per_socket:?}"
        );
        for socket in [901_i32, 902_i32] {
            let body = per_socket.get(&socket).expect("每个玩家都应收受击帧");
            let cm = CommandMessage::from_bytes(body).expect("12B");
            assert_eq!(
                u16::from_le_bytes([body[4], body[5]]),
                mir2_protocol::messages::SM_STRUCK
            );
            // 生产默认 = 客户端 `HIGHHP` 布局（`param=LoWord(HP)=12, tag=HiWord(HP)=0`）；
            // `=0` ⇒ oracle 布局（`param=HP=12, tag=MaxHP=100`）。HP=12<65536 ⇒ HiWord=0。
            let want = if game_svr::smframe::client_layout_enabled() {
                (victim, 12, 0, 7)
            } else {
                (victim, 12, 100, 7)
            };
            assert_eq!(
                (cm.recog, cm.param, cm.tag, cm.series),
                want,
                "socket={socket} 的受击帧头 = (受击者, HP, MaxHP, 伤害)"
            );
        }
        assert_eq!(
            sessions["victim"].state.wabil.hp, 12,
            "受击后世界 HP 同步回会话 WAbil"
        );
    }

    /// **片㉜**：**怪物目标**也要广播受击帧 —— 怪物自身无连接，但视野内玩家收到 ⇒ 真客户端
    /// 能看到怪掉血/伤害（DoD③「能攻击造成伤害」）。
    ///
    /// 红检：把广播循环改回「只发受击者自己」（旧实现）⇒ 怪物不在 `online` ⇒ **零帧**，本用例必红。
    #[test]
    fn combat_downlink_broadcasts_struck_for_monster_target() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let monster = {
            let mut e = mir2_world::Entity::new(0, "mon".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_MONSTER;
            e.hp = 200;
            e.max_hp = 200;
            world.add_entity(e)
        };
        let attacker = {
            let mut e = mir2_world::Entity::new(0, "atk".to_string(), 11, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let observer = {
            let mut e = mir2_world::Entity::new(0, "obs".to_string(), 13, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            monster,
            downlink::ActorDisplay::new(0, 0, 222, 0, 0, 255, Vec::new()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uo".into(),
                chr_name: "obs".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 902,
                actor_id: observer,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();

        let rec = mir2_world::TickRecord {
            attacks: vec![(
                attacker,
                monster,
                mir2_world::AttackOutcome {
                    power: 30,
                    hit: true,
                    damage: 20,
                    killed: false,
                    target_hp_after: 180,
                },
            )],
            ..Default::default()
        };
        drain_combat_downlink(&rec, &world, &displays, &online, &mut sessions, &gates);
        let mut bodies = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { socket, body } = m {
                assert_eq!(socket, 902, "只有观察者在线 ⇒ 只给他发");
                bodies.push(body);
            }
        }
        assert_eq!(
            bodies.len(),
            1,
            "怪物受击 ⇒ 视野内玩家收 1 帧 SM_STRUCK（旧实现 = 0 帧）"
        );
        let cm = CommandMessage::from_bytes(&bodies[0]).expect("12B");
        assert_eq!(
            u16::from_le_bytes([bodies[0][4], bodies[0][5]]),
            mir2_protocol::messages::SM_STRUCK
        );
        // 生产默认 = 客户端 `HIGHHP` 布局（`param=LoWord(HP)=180, tag=HiWord(HP)=0`）。
        let want = if game_svr::smframe::client_layout_enabled() {
            (monster, 180, 0, 20)
        } else {
            (monster, 180, 200, 20)
        };
        assert_eq!(
            (cm.recog, cm.param, cm.tag, cm.series),
            want,
            "SM_STRUCK 头 = (怪物, 扣血后 HP, MaxHP, 伤害)"
        );
    }

    /// **M3⑨-3 帧面残余**：`rec.slave_self_deliveries` 里一条 `RM_MASTERDIEMUTINY` ⇒
    /// `drain_slave_mutiny_downlink` 给**叛变宝宝视野内的在线玩家**发
    /// `SM_CHANGENAMECOLOR(656)`（无尾，`Param = GetChrColor`）与 `SM_USERNAME(42)`
    /// （尾 = `EncodeString(FilterShowName(ChrName))`）。
    ///
    /// 锚：`PlayObject.Base.cs:351-352`（`RefNameColor(); RefShowName();`）→
    /// `BaseObject.cs:730-733/1174-1177` → `PlayObject.Message.cs:1662-1664/1677-1679`。
    ///
    /// 红检：删掉 `drain_slave_mutiny_downlink` 的名帧（或把色帧/名帧互换）⇒ 本用例必红（帧序/条数）。
    #[test]
    fn slave_mutiny_downlink_emits_namecolor_then_username() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let master = {
            let mut e = mir2_world::Entity::new(0, "master".to_string(), 9, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e.death = true;
            world.add_entity(e)
        };
        // 叛变后的宝宝：`Master == null`（`process_slave_mutiny` 已置）⇒ `GetChrColor` = `NameColor`(255)。
        let slave = {
            let mut e = mir2_world::Entity::new(0, "骷髅2".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_MONSTER;
            world.add_entity(e)
        };
        let near = {
            let mut e = mir2_world::Entity::new(0, "near".to_string(), 12, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let far = {
            let mut e = mir2_world::Entity::new(0, "far".to_string(), 40, 40);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut online: OnlineRegistry = Vec::new();
        for (i, (name, socket, actor)) in [("near", 901_i32, near), ("far", 902, far)]
            .into_iter()
            .enumerate()
        {
            online_set(
                &mut online,
                OnlineEntry {
                    account: format!("u{i}"),
                    chr_name: name.into(),
                    session_id: i as i32 + 1,
                    gate_idx: 0,
                    socket,
                    actor_id: actor,
                },
            );
        }
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        let rec = mir2_world::TickRecord {
            slave_self_deliveries: vec![mir2_world::slave::SelfDelayOutcome {
                actor_id: master,
                ident: mir2_world::slave::RM_MASTERDIEMUTINY,
                mutinied: vec![slave],
                ghosted: Vec::new(),
                mag_healing: None,
                ..Default::default()
            }],
            ..Default::default()
        };
        let cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let sent = drain_slave_mutiny_downlink(&rec, &world, &online, &gates, &cfg, 12);
        assert_eq!(sent, 2, "只给视野内玩家（near）发 2 帧");
        let mut bodies: Vec<(i32, Vec<u8>)> = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { socket, body } = m {
                bodies.push((socket, body));
            }
        }
        assert!(
            bodies.iter().all(|(s, _)| *s == 901),
            "远距（40,40）观察者不得收帧：{bodies:?}"
        );
        assert_eq!(bodies.len(), 2, "色帧 + 名帧");
        let cm0 = CommandMessage::from_bytes(&bodies[0].1).expect("12B");
        assert_eq!(cm0.ident, mir2_protocol::messages::SM_CHANGENAMECOLOR);
        assert_eq!(
            (cm0.recog, cm0.param, cm0.tag, cm0.series),
            (slave, 255, 0, 0)
        );
        assert_eq!(bodies[0].1.len(), 12, "SM_CHANGENAMECOLOR 无尾");
        let cm1 = CommandMessage::from_bytes(&bodies[1].1).expect("12B");
        assert_eq!(cm1.ident, mir2_protocol::messages::SM_USERNAME);
        assert_eq!(
            (cm1.recog, cm1.param, cm1.tag, cm1.series),
            (slave, 255, 0, 0)
        );
        assert_eq!(
            mir2_protocol::edcode::decode(&bodies[1].1[12..]),
            downlink::gbk("骷髅"),
            "尾 = EncodeString(FilterShowName(ChrName))（“骷髅2” ⇒ “骷髅”）"
        );
    }

    /// **M3⑨-3 帧面残余（出队序，reviewer-6 F-1）**：多只宝宝叛变时，按观察者 `MsgQueue` 的
    /// **堆出队序**（`BaseObject.Message.cs:181` 的 `(byte)wIdent` 入队 + `ActorEntity.cs:16` 的
    /// `PriorityQueue`）—— 优先级字节 154(色) < 165(名) ⇒ 所有色帧先于所有名帧；但**同优先级不是
    /// 入队序**（.NET 8 为 4 叉堆）⇒ mutinied `[s2,s1]` 的两条名帧出队为 `名(s1),名(s2)`（**反序**）。
    ///
    /// 堆算法逐位对照见 [`game_svr::msgqueue`] 的 `matches_dotnet_priority_queue_dequeue_order`
    /// （n=1..12 与 net8.0.26 实跑 `dotnet` 对齐）。
    ///
    /// 红检：① `msgqueue` 换成「按优先级稳定排序」（入队序）⇒ 名帧序反过来，本断言必红；
    ///       ② 删名帧 / 把色帧名帧互换 ⇒ 帧数/种类必红。
    #[test]
    fn slave_mutiny_downlink_follows_msgqueue_heap_order() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let master = {
            let mut e = mir2_world::Entity::new(0, "master".to_string(), 9, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e.death = true;
            world.add_entity(e)
        };
        let mut slaves = Vec::new();
        for (name, x) in [("s1", 10_i32), ("s2", 11)] {
            let mut e = mir2_world::Entity::new(0, name.to_string(), x, 10);
            e.race = mir2_world::ACTOR_RACE_MONSTER;
            slaves.push(world.add_entity(e));
        }
        let obs = {
            let mut e = mir2_world::Entity::new(0, "obs".to_string(), 12, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uo".into(),
                chr_name: "obs".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 905,
                actor_id: obs,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        // `mutinied` 序 = `SlaveList` 末尾往前 ⇒ [s2, s1]。
        let rec = mir2_world::TickRecord {
            slave_self_deliveries: vec![mir2_world::slave::SelfDelayOutcome {
                actor_id: master,
                ident: mir2_world::slave::RM_MASTERDIEMUTINY,
                mutinied: vec![slaves[1], slaves[0]],
                ghosted: Vec::new(),
                mag_healing: None,
                ..Default::default()
            }],
            ..Default::default()
        };
        let cfg = mir2_data::pet_slave::PetSlaveConfig::default();
        let sent = drain_slave_mutiny_downlink(&rec, &world, &online, &gates, &cfg, 12);
        assert_eq!(sent, 4, "2 只宝宝 × (色 + 名)");
        let mut idents: Vec<(u16, i32)> = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, .. } = m {
                let cm = CommandMessage::from_bytes(&body).expect("12B");
                idents.push((cm.ident, cm.recog));
            }
        }
        assert_eq!(
            idents,
            vec![
                (mir2_protocol::messages::SM_CHANGENAMECOLOR, slaves[1]),
                (mir2_protocol::messages::SM_CHANGENAMECOLOR, slaves[0]),
                (mir2_protocol::messages::SM_USERNAME, slaves[0]),
                (mir2_protocol::messages::SM_USERNAME, slaves[1]),
            ],
            "入队序 色(s2),名(s2),色(s1),名(s1) ⇒ oracle 4 叉堆出队 色(s2),色(s1),名(s1),名(s2)"
        );
    }

    /// **D①（击杀经验下行）**：`TickRecord::exp_awards` 一条 ⇒ `drain_combat_downlink` 给获得者发
    /// `SM_WINEXP(44)`（`Recog=总量`、`Param=LoWord(增量)`、`Tag=HiWord(增量)`、无尾），并把世界实体的
    /// 经验/等级同步回会话（存档 `build_save_record` 读 `sg.equip.abil`）。
    /// 红检：把 `sm_winexp` 的 `param`/`tag` 互换 ⇒ 头断言必红；不同步会话 ⇒ 会话 exp 断言必红。
    #[test]
    fn exp_downlink_sends_sm_winexp_and_syncs_session() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let killer = {
            let mut e = mir2_world::Entity::new(0, "killer".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        world.entities.get_mut(killer).unwrap().exp = 1234;
        world.entities.get_mut(killer).unwrap().level = 9;
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            killer,
            downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"killer".to_vec()),
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uk".into(),
                chr_name: "killer".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 902,
                actor_id: killer,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("killer".into(), test_session_ground(killer));

        // 增量 0x0001_0203（Param=0x0203、Tag=0x0001），总量 1234。
        let rec = mir2_world::TickRecord {
            exp_awards: vec![(killer, 0x0001_0203, true, 9)],
            ..Default::default()
        };
        drain_combat_downlink(&rec, &world, &displays, &online, &mut sessions, &gates);
        let mut bodies = Vec::new();
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { socket, body } = m {
                assert_eq!(socket, 902);
                bodies.push(body);
            }
        }
        assert_eq!(bodies.len(), 1, "只有经验一帧");
        let cm = CommandMessage::from_bytes(&bodies[0]).expect("12B");
        assert_eq!(cm.ident, mir2_protocol::messages::SM_WINEXP);
        assert_eq!(cm.recog, 1234, "Recog = 加完后的 Abil.Exp（总量）");
        assert_eq!(cm.param, 0x0203, "Param = LoWord(增量)");
        assert_eq!(cm.tag, 0x0001, "Tag = HiWord(增量)");
        assert_eq!(cm.series, 0);
        assert_eq!(bodies[0].len(), 12, "SM_WINEXP 无尾");
        let sg = &sessions["killer"];
        assert_eq!(sg.equip.abil.exp, 1234, "会话基能力 exp 同步（存档口径）");
        assert_eq!(sg.equip.abil.level, 9);
        assert_eq!(sg.state.wabil.exp, 1234);
        assert_eq!(sg.state.wabil.level, 9);
    }

    /// **52 帧尾的布局选路（`ability_tail`）**：生产默认 `client_layout=true` ⇒ 冻结客户端 58B
    /// `TAbility`（`HP@22` / `MaxHP@30`）；`false` ⇒ oracle 40B `EncodeMessage(WAbil)`。
    ///
    /// 红检（改坏必红）：`ability_tail` 两支互换（或恒走 `encode_ability`）⇒
    /// `oracle.len() == 40` / `client.len() == 58` / `client[22..26] == hp` 必红。
    #[test]
    fn ability_tail_switches_between_client_58_and_oracle_40() {
        let mut w = test_ability();
        w.hp = 19;
        w.mp = 15;
        w.max_hp = 19;
        w.max_mp = 15;
        let oracle = ability_tail(&w, false);
        let client = ability_tail(&w, true);
        assert_eq!(oracle.len(), 40, "oracle 支 = 40B EncodeMessage(WAbil)");
        assert_eq!(client.len(), 58, "client 支 = 58B TAbility");
        assert_eq!(
            i32::from_le_bytes(client[22..26].try_into().unwrap()),
            i32::from(w.hp),
            "58B 布局的 HP 在 offset 22（`Grobal2.pas:2167-2184`）"
        );
        assert_eq!(
            i32::from_le_bytes(client[30..34].try_into().unwrap()),
            i32::from(w.max_hp),
            "58B 布局的 MaxHP 在 offset 30"
        );
        assert_ne!(oracle, client, "两种布局不得同字节");
    }

    /// **D②（升级链下行）**：一条 `leveled=true` 的 `exp_awards` ⇒ 帧序按 oracle `MsgQueue`
    /// **出队序**（优先级字节升序）
    /// `SM_HEALTHSPELLCHANGED(53) → SM_WINEXP(44) → SM_LEVELUP(45) → SM_ABILITY(52) → SM_SUBABILITY(752)`
    /// （reviewer-6 `c5a90bf4` F-1：53 的优先级字节 68 < 44 的 139 < 45 的 150），
    /// 不是源码入队序 44→45→53。`SM_LEVELUP` 头 = `(total_exp, new_level, 0, 0)`；
    /// `RecalcLevelAbilitys()+RecalcAbilitys()` 把 `MaxHP/MaxMP` 从 0 提到等级派生值，然后
    /// `IncHealthSpell(2000,2000)` 按**新** `MaxHP/MaxMP` 截断 ⇒ 满血满蓝；世界实体同步到同一 `WAbil`。
    ///
    /// 红检：① 交换 `sm_levelup` 的 `recog`/`param` ⇒ `SM_LEVELUP` 头断言必红；
    /// ② 删 `drain_levelup_healthspell` 的 `IncHealthSpell(2000,2000)` ⇒ `hp == max_hp` 必红；
    /// ③ 不调 `recalc_session_ability` ⇒ `max_hp == 0` 必红；
    /// ④（F-1 红检）交换 `drain_kill_exp_chain` 的前两行（把 53 落到 44 之后）
    ///   ⇒ `idents` 序断言必红。
    #[test]
    fn levelup_downlink_sends_levelup_frames_heals_and_syncs_entity() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let killer = {
            let mut e = mir2_world::Entity::new(0, "killer".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        {
            let e = world.entities.get_mut(killer).unwrap();
            e.exp = 500;
            e.level = 11;
            e.max_exp = 1000;
            e.hp = 10;
            e.max_hp = 20;
        }
        let displays = downlink::DisplayTable::new();
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uk".into(),
                chr_name: "killer".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 903,
                actor_id: killer,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(killer);
        sg.equip.abil.level = 10; // drain_combat_downlink 会把它同步成 11
        sg.state.wabil.level = 10;
        sg.state.wabil.hp = 10; // 升级前残血
        sg.state.wabil.mp = 5;
        sessions.insert("killer".into(), sg);

        let rec = mir2_world::TickRecord {
            exp_awards: vec![(killer, 500, true, 11)],
            ..Default::default()
        };
        // 与 `sim_loop` 同一条链：oracle 出队序 53(68) → 44(139) → 45(150)/52/752。
        drain_kill_exp_chain(
            &rec,
            &mut world,
            &displays,
            &online,
            &mut sessions,
            &gates,
            &game_svr::ability::StdItemCatalog::new(),
            12,
            true, // 生产默认 = 冻结客户端 58B（`ability_tail`）
        );
        let mut bodies: Vec<Vec<u8>> = Vec::new();
        let mut frames = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            assert_eq!(socket, 903);
            frames.push(CommandMessage::from_bytes(&body).expect("12B"));
            bodies.push(body);
        }
        let idents: Vec<u16> = frames.iter().map(|cm| cm.ident).collect();
        assert_eq!(
            idents,
            vec![
                mir2_protocol::messages::SM_HEALTHSPELLCHANGED,
                mir2_protocol::messages::SM_WINEXP,
                mir2_protocol::messages::SM_LEVELUP,
                mir2_protocol::messages::SM_ABILITY,
                mir2_protocol::messages::SM_SUBABILITY,
            ],
            "升级帧序 = HEALTHSPELLCHANGED(53) → WINEXP(44) → LEVELUP(45) → ABILITY(52) → SUBABILITY(752)"
        );
        let lv = &frames[2];
        assert_eq!((lv.recog, lv.param, lv.tag, lv.series), (500, 11, 0, 0));
        let sg = &sessions["killer"];
        assert!(
            sg.state.wabil.max_hp > 0,
            "RecalcLevelAbilitys+RecalcAbilitys 必须给 MaxHP 等级派生值（非 0）"
        );
        assert!(
            sg.state.wabil.hp == sg.state.wabil.max_hp,
            "IncHealthSpell(2000,2000) 应按升级后的 MaxHP 截断 ⇒ 满血: {:?}",
            sg.state.wabil
        );
        assert_eq!(sg.state.wabil.mp, sg.state.wabil.max_mp, "MP 同样满额");
        assert_eq!(sg.equip.abil.level, 11, "会话基能力等级 = 升级后");
        // F-2：`GetExp` 的两处 `AddBodyLuck` 按 oracle 次序落账：500*0.002 + 100 = 101.0；
        // `BodyLuckLevel = Convert.ToInt32(101/5000) = 0`。
        assert_eq!(
            sg.equip.body_luck, 101.0,
            "GetExp: dwExp*0.002（1.0）与升级 +100 均须累加"
        );
        assert_eq!(sg.equip.body_luck_level, 0);
        // 52 的尾 = **冻结客户端 58B `TAbility`**（升级重算后的值；生产默认 `client_layout=true`）。
        // bodies = [53,44,45,52,752] ⇒ 52 在 index 3。oracle 40B 支由
        // `record::encode_ability_matches_golden_frame_12_tail` 与 `ability_tail` 单测钉住。
        assert_eq!(
            &bodies[3][12..],
            &mir2_protocol::edcode::encode(&record::encode_ability_client(&sg.state.wabil)),
            "SM_ABILITY 尾 = Encode(58B TAbility)"
        );
        // 世界实体（战斗权威值）同步。
        let e = world.entities.get(killer).unwrap();
        assert_eq!(e.level, 11);
        assert!(e.max_hp > 0 && e.hp == e.max_hp, "实体 HP/MaxHP 同步");
        assert_eq!(e.max_hp, sg.state.wabil.max_hp);
    }

    /// **F-1（同 tick 去重）**：恢复段已产生 53 的对象，若本 tick 进升级块，
    /// `SendUpdateMsg(RM_HEALTHSPELLCHANGED)`（`BaseObject.Message.cs:275-304`）会把恢复段入队的 53
    /// 移除 ⇒ `drain_recovery` 不得回帧（升级段由 `drain_levelup_healthspell` 出唯一一条）。
    ///
    /// 红检：删掉 `drain_recovery` 的 `superseded_healthspell.contains(...)` 分支 ⇒ 本用例必红（① 收到帧）。
    #[test]
    fn recovery_healthspell_is_superseded_by_levelup_in_same_tick() {
        use std::collections::{HashMap, HashSet};
        let mut world = mir2_world::World::new(32, 32);
        let hid = {
            let mut e = mir2_world::Entity::new(0, "hero".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hid,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        // 「恢复段必命中」的会话：池里 20 点 IncHealth、HP 未满、tick 初值 0（真实时钟远超阈值）。
        let mk = || {
            let mut sg = test_session_ground(hid);
            sg.state.wabil.hp = 10;
            sg.state.wabil.max_hp = 100;
            sg.recovery = game_svr::recover::Recovery::new(0);
            sg.recovery.inc_health = 20;
            sg
        };

        // ① 在「本 tick 进升级块」集合里 ⇒ 不回帧（被升级段的 53 取代），但状态照常消费。
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), mk());
        let superseded: HashSet<i32> = [hid].into_iter().collect();
        drain_recovery(&mut sessions, &world, &online, &gates, 12, &superseded);
        assert!(
            rx0.try_recv().is_err(),
            "升级块取代恢复段 53 ⇒ 本段不得回帧"
        );
        assert_eq!(
            sessions["hero"].recovery.inc_health, 15,
            "HP/MP 与 Inc* 的状态变更仍照常发生（20 - PerHealth 5）"
        );

        // ② 不在集合里 ⇒ 照常回帧（自见一条）。
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), mk());
        drain_recovery(&mut sessions, &world, &online, &gates, 12, &HashSet::new());
        let (cm, frame_body) = match rx0.try_recv() {
            Ok(SimToGate::SendFrame { body, socket }) => {
                assert_eq!(socket, 901);
                (CommandMessage::from_bytes(&body).expect("12B"), body)
            }
            _ => panic!("未取代时必须有 53 帧"),
        };
        assert_eq!(cm.ident, mir2_protocol::messages::SM_HEALTHSPELLCHANGED);
        // **①/② 真机根因（卡 `openmir2-client-e2e-enter-gaps`）**：冻结客户端 `HIGHHP=True`
        // （`Grobal2.pas:39`）的 53 支从**尾**读 `TCharDesc`（`ClMain.pas:10220`）⇒ 生产默认
        // （`client_layout_enabled()`）必须带 12B 尾，否则客户端 HUD 归零、`CanRun` 拒绝跑。
        // 红检：把 `sm_healthspellchanged_frame` 的默认支改回 header-only ⇒ 下面断言必红。
        if game_svr::smframe::client_layout_enabled() {
            let desc = mir2_protocol::edcode::decode(&frame_body[12..]);
            assert_eq!(
                desc.len(),
                12,
                "53 尾 = TCharDesc（12B，HIGHHP 客户端要求）"
            );
            let le = |o: usize| i32::from_le_bytes(desc[o..o + 4].try_into().unwrap());
            assert_eq!(
                le(0),
                i32::from(sessions["hero"].state.wabil.hp),
                "Feature = HP"
            );
            assert_eq!(
                le(4),
                i32::from(sessions["hero"].state.wabil.mp),
                "Status = MP"
            );
            assert_eq!(
                le(8),
                i32::from(sessions["hero"].state.wabil.max_hp),
                "StatusEx = MaxHP"
            );
        }
    }

    /// **F-2（`AddBodyLuck`）**：`PlayObject.AddBodyLuck`（`PlayObject.cs:4304-4323`）的纯函数口径——
    /// 两个 `±5*BODYLUCKUNIT` 累加门 + `Convert.ToInt32`（**银行家舍入**）派生 `BodyLuckLevel`
    /// （clamp `[-10,5]`）。`BodyLuck` 是 `characters.BodyLuck double(10,3)`，被 `scoped_diff` 逐字节比。
    ///
    /// 红检：把 `round_ties_even()` 换成 `round()` ⇒ `2500/5000=0.5` 的用例必红（期望 0，实得 1）。
    #[test]
    fn add_body_luck_matches_oracle_vectors() {
        // (初值, dLuck, 期望 BodyLuck, 期望 BodyLuckLevel)
        let cases: &[(f64, f64, f64, i32)] = &[
            (0.0, 0.0, 0.0, 0),
            (2500.0, 0.0, 2500.0, 0), // Convert.ToInt32(0.5) = 0（midpoint-to-even）
            (7500.0, 0.0, 7500.0, 2), // 1.5 → 2
            (-2500.0, 0.0, -2500.0, 0), // -0.5 → 0
            (24950.0, 100.0, 25050.0, 5), // 5.01 → clamp 5
            (25000.0, 100.0, 25000.0, 5), // 正门：>= 5*unit ⇒ 不加
            (25050.0, -100.0, 24950.0, 5), // 负向可加（> -5*unit）
            (-24950.0, -100.0, -25050.0, -5), // -5.01 → -5
            (-25000.0, -100.0, -25000.0, -5), // 负门：<= -5*unit ⇒ 不加
            (0.0, 24999.0, 24999.0, 5), // 4.9998 → 5
        ];
        for (init, d, exp_luck, exp_level) in cases {
            let mut luck = *init;
            let mut level = 0;
            add_body_luck(&mut luck, &mut level, *d);
            assert_eq!(luck, *exp_luck, "BodyLuck: init={init} d={d}");
            assert_eq!(level, *exp_level, "BodyLuckLevel: init={init} d={d}");
        }
    }

    /// **F-2（落库）**：击杀后会话的 `BodyLuck` 必须写进 `characters.BodyLuck`（`MakeSaveRcd` 口径）。
    /// `drain_combat_downlink` 按 oracle 次序（`dwExp*0.002` 然后升级 `+100`）累加 ⇒
    /// `build_save_record` 原样带出（`WorldServer.cs:1290 save playerInfo.BodyLuck = playObject.BodyLuck`）。
    ///
    /// 红检：把 `rec.data.body_luck = sg.equip.body_luck` 删掉 ⇒ 存档断言必红（保留加载值）。
    #[test]
    fn body_luck_accumulates_on_getexp_and_persists() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(64, 64);
        let killer = {
            let mut e = mir2_world::Entity::new(0, "killer".to_string(), 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        {
            let e = world.entities.get_mut(killer).unwrap();
            e.exp = 100;
            e.level = 11;
            e.max_exp = 1000;
        }
        let displays = downlink::DisplayTable::new();
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "uk".into(),
                chr_name: "killer".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 905,
                actor_id: killer,
            },
        );
        let (tx0, _rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(killer);
        sg.equip.abil.level = 10;
        sg.state.wabil.level = 10;
        sessions.insert("killer".into(), sg);

        // 非升级（`leveled=false`）⇒ 只加 `dwExp*0.002 = 5000`；`BodyLuckLevel = 1`。
        let rec = mir2_world::TickRecord {
            exp_awards: vec![(killer, 2_500_000, false, 11)],
            ..Default::default()
        };
        drain_combat_downlink(&rec, &world, &displays, &online, &mut sessions, &gates);
        let sg = sessions.get("killer").unwrap();
        assert_eq!(sg.equip.body_luck, 5000.0, "dwExp*0.002 累加");
        assert_eq!(sg.equip.body_luck_level, 1, "Convert.ToInt32(5000/5000)=1");

        let saved = SavedHuman {
            account: "acct".into(),
            record: stage6_record(),
            enter_map: "0".into(),
        };
        let out = build_save_record(&saved, "killer", &world, sg, None);
        assert_eq!(
            out.data.body_luck, 5000.0,
            "characters.BodyLuck 必须带出会话的实时 BodyLuck"
        );
    }

    /// **⑤-4 返工 F-2**：`ClientRepairItem`（`PlayObject.Operate.cs:1585-1597`）的 **BUG-REPLICA**
    /// —— 未命中 ⇒ 修最后一件；空背包 ⇒ 无目标；命中 ⇒ 命中项（即使不是最后一件）。
    /// 改坏（把 `or_else(...last)` 删掉、改成未命中即 return）⇒ 第一/三两个断言红。
    #[test]
    fn repair_target_index_replicates_oracle_last_item_bug() {
        let mut cat = game_svr::ability::StdItemCatalog::new();
        cat.insert(
            1,
            mir2_data::models::StdItem {
                name: "金创药(小量)".to_string(),
                ..Default::default()
            },
        );
        let item = |make_index: i32, index: u16| game_svr::bag::BagItem {
            make_index,
            index,
            dura: 0,
            dura_max: 0,
            desc: [0; 14],
        };
        let list = vec![item(9, 1), item(10, 1), item(11, 1)];
        // 未命中 ⇒ 最后一件（下标 2），不是 None。
        assert_eq!(
            repair_target_index(&list, &cat, 999, "金创药(小量)"),
            Some(2),
            "oracle bug：未命中 ⇒ 修最后一件"
        );
        // 命中第 0 件（名字 `OrdinalIgnoreCase`）。
        assert_eq!(repair_target_index(&list, &cat, 9, "金创药(小量)"), Some(0));
        // 空背包 ⇒ None（oracle `userItem` 仍为 null）。
        assert_eq!(repair_target_index(&[], &cat, 9, "金创药(小量)"), None);
    }

    /// **⑤-4 返工（自报 Important）**：shop 帧的线上尾 = `EDCode.EncodeString(GBK 原文)`
    /// （oracle `SendDefMessage` 非空尾走 `SendSocket(ClientMsg, EDCode.EncodeString(sMsg))`，
    /// `PlayObject.Socket.cs:26-43`）；空尾保持空（header-only 帧不变）。
    /// 改坏（退回 `&f.tail` 裸拼）⇒ 中间两个断言红。
    #[test]
    fn emit_shop_frames_edcodes_tail_like_send_def_message() {
        let (tx, mut rx) = mpsc::unbounded_channel();
        let tail = game_svr::downlink::gbk("商人乙/对不起!我不能帮你修理这个物品。");
        let frames = vec![
            game_svr::shop::ShopFrame {
                ident: mir2_protocol::messages::SM_MERCHANTSAY,
                recog: 5_555,
                param: 0,
                tag: 0,
                series: 1,
                tail: tail.clone(),
                tail_encoded: false,
            },
            game_svr::shop::ShopFrame {
                ident: mir2_protocol::messages::SM_USERREPAIRITEM_FAIL,
                recog: 0,
                param: 0,
                tag: 0,
                series: 0,
                tail: Vec::new(),
                tail_encoded: false,
            },
        ];
        emit_shop_frames(&tx, 7, &frames);
        let (sock1, body1) = match rx.try_recv().expect("第一帧") {
            SimToGate::SendFrame { socket, body } => (socket, body),
            _ => panic!("非 SendFrame"),
        };
        let (sock2, body2) = match rx.try_recv().expect("第二帧") {
            SimToGate::SendFrame { socket, body } => (socket, body),
            _ => panic!("非 SendFrame"),
        };
        assert_eq!((sock1, sock2), (7, 7));
        assert_eq!(
            &body1[..12],
            &game_svr::smframe::command_header(
                5_555,
                mir2_protocol::messages::SM_MERCHANTSAY,
                0,
                0,
                1
            )
        );
        assert_eq!(&body1[12..], &mir2_protocol::edcode::encode(&tail));
        assert_ne!(&body1[12..], &tail[..], "线上尾不是裸 GBK（EDCode 会变换）");
        // 空尾：仍只发 12B 头（`EncodeString("")` 不追加字节）。
        assert_eq!(
            &body2[..12],
            &game_svr::smframe::command_header(
                0,
                mir2_protocol::messages::SM_USERREPAIRITEM_FAIL,
                0,
                0,
                0
            )
        );
        assert_eq!(body2.len(), 12, "空尾 ⇒ header-only 不变");
    }

    /// **M3⑦-实现 4**：`CM_PICKUP` 的归属组队分支接上真注册表
    /// （oracle `PlayObject.Base.cs:38-54` `ClientPickUpItemIsOfGroup`）：非组员不可拾、
    /// 同组成员可拾。
    ///
    /// 改坏必红：把 `handle_ground_cmd` 里的 `group_owner`/`group_member_actor_ids` 换回
    /// `0`/`&[]` ⇒ 情形 B 收不到 `SM_GOLDCHANGED`、会话金币不变，两条断言必红。
    #[test]
    fn pickup_group_attribution_uses_registry() {
        use std::collections::HashMap;

        let mut world = mir2_world::World::new(32, 32);
        world.item_catalog = vec![mir2_data::StdItem {
            name: "金币".into(),
            ..Default::default()
        }];
        let hero = world.add_entity({
            let mut e = mir2_world::Entity::new(1, "hero", 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e
        });
        let mate = world.add_entity(mir2_world::Entity::new(2, "mate", 11, 10));
        let (gx, gy) = (11, 10);
        let count = 300;
        // 地面金币归属 = mate（`MapItem.OfBaseObject`）。
        assert!(world.maps[0].add_floor_item(
            gx,
            gy,
            mate,
            mir2_world::map::FloorItemMeta {
                kind: mir2_world::map::FloorItemKind::Gold,
                index: 0,
                count,
                item_id: mate,
                of_base_object: mate,
            },
            0,
        ));
        {
            let e = world.entities.get_mut(hero).expect("hero 必在实体表");
            e.x = gx;
            e.y = gy;
        }

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert(
            "hero".into(),
            SessionGround {
                state: game_svr::ground::GroundState {
                    item_list: Vec::new(),
                    gold: 0,
                    wabil: test_ability(),
                },
                storage: storage::StorageState::new(),
                actor_id: hero,
                game_gold: 0,
                soft_version_date: 0,
                client_tick: 0,
                game_point: 0,
                sys_msg: None,
                use_items: vec![None; game_svr::ability::USE_ITEMS_LEN],
                sub: game_svr::ability::SubAbility::first_call(),
                hit_speed: 0,
                equip: test_equip_inputs(),
                recovery: game_svr::recover::Recovery::new(0),
                stamina: game_svr::stamina::Stamina::new(0),
                show_hp: false,
                abil_see_heal_gauge: false,
                user_unlock_durg: false,
                hunger_status: 0,
                query_bag_items_tick: None,
                bo_reconnection: false,
                bo_soft_close: false,
                bo_emergency_close: false,
                is_can_deal: true,
                click_npc_time: None,
                goto_npc_label: String::new(),
                val_type: 0,
                val_label: 0,
                val_npc_type: 0,
                mns_val: vec![String::new(); 100],
                mnm_val: vec![0; 100],
                save_rcd_tick: 0,
            },
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let cfg = GroundCfg {
            human_max_gold: 10_000_000,
            floor_item_can_pick_up_time: 120_000,
            control_drop_item: false,
            in_safe_disable_drop: false,
            can_drop_price: 500,
            can_drop_gold: 1000,
            drop_item_rage: 3,
        };
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
        };
        let catalog = game_svr::ability::StdItemCatalog::new();

        // 情形 A：hero 与 mate **未组队** ⇒ 归属既非自己也非组员 ⇒ 拒绝（无帧、金币不变）。
        handle_ground_cmd(
            game_svr::ground::CM_PICKUP,
            u16::try_from(gx).unwrap(),
            u16::try_from(gy).unwrap(),
            None,
            "hero",
            901,
            &std::collections::HashMap::new(),
            &world,
            &mut sessions,
            &online,
            &gates,
            &cfg,
            &colors,
            &catalog,
            None,
        );
        assert!(
            matches!(rx0.try_recv(), Err(mpsc::error::TryRecvError::Empty)),
            "未组队 ⇒ 不得拾取他人归属物（oracle Base.cs:57-63）"
        );
        assert_eq!(sessions.get("hero").unwrap().state.gold, 0);

        // 情形 B：hero 与 mate 同组（hero 团长）⇒ `ClientPickUpItemIsOfGroup(mate)` 成立 ⇒ 可拾。
        world.entities.get_mut(mate).unwrap().allow_group = true;
        let _ = world.party_create_group(hero, "mate", &mir2_world::PartyConfig::default());
        assert_eq!(world.entities.get(hero).unwrap().group_owner, hero);
        assert_eq!(world.entities.get(mate).unwrap().group_owner, hero);
        handle_ground_cmd(
            game_svr::ground::CM_PICKUP,
            u16::try_from(gx).unwrap(),
            u16::try_from(gy).unwrap(),
            None,
            "hero",
            901,
            &std::collections::HashMap::new(),
            &world,
            &mut sessions,
            &online,
            &gates,
            &cfg,
            &colors,
            &catalog,
            None,
        );
        let body = match rx0.try_recv() {
            Ok(SimToGate::SendFrame { body, socket }) => {
                assert_eq!(socket, 901);
                body
            }
            other => panic!("组员归属物应可拾并回 SM_GOLDCHANGED，实收 {other:?}"),
        };
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body).expect("body >= 12B");
        assert_eq!(cm.ident, mir2_protocol::messages::SM_GOLDCHANGED);
        assert_eq!(cm.recog, count);
        assert_eq!(sessions.get("hero").unwrap().state.gold, count);
    }

    /// **M3⑦-实现 4**：`CM_TAKEOFFITEM` 的 `Dealing` 守卫接上真交易态
    /// （oracle `PlayObject.Operate.cs:501` `if (!Dealing && btWhere < 13)`）。
    ///
    /// 改坏必红：把 `handle_bag_cmd` 的 `dealing` 换回 `false` ⇒ 卸装成功、物品从 `UseItems`
    /// 移除，两条断言（`recog == -1` / `use_items[0].is_some()`）必红。
    #[test]
    fn bag_takeoff_blocked_while_dealing() {
        use std::collections::HashMap;

        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "木剑".into(),
                std_mode: 5,
                ..Default::default()
            },
        );

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut use_items: Vec<Option<game_svr::bag::BagItem>> =
            vec![None; game_svr::ability::USE_ITEMS_LEN];
        use_items[0] = Some(game_svr::bag::BagItem {
            make_index: 60001,
            index: 1,
            dura: 10,
            dura_max: 10,
            desc: [0u8; 14],
        });
        sessions.insert(
            "hero".into(),
            SessionGround {
                state: game_svr::ground::GroundState {
                    item_list: Vec::new(),
                    gold: 123,
                    wabil: test_ability(),
                },
                storage: storage::StorageState::new(),
                actor_id: 42,
                game_gold: 0,
                soft_version_date: 0,
                client_tick: 0,
                game_point: 0,
                sys_msg: None,
                use_items,
                sub: game_svr::ability::SubAbility::first_call(),
                hit_speed: 0,
                equip: test_equip_inputs(),
                recovery: game_svr::recover::Recovery::new(0),
                stamina: game_svr::stamina::Stamina::new(0),
                show_hp: false,
                abil_see_heal_gauge: false,
                user_unlock_durg: false,
                hunger_status: 0,
                query_bag_items_tick: None,
                bo_reconnection: false,
                bo_soft_close: false,
                bo_emergency_close: false,
                is_can_deal: true,
                click_npc_time: None,
                goto_npc_label: String::new(),
                val_type: 0,
                val_label: 0,
                val_npc_type: 0,
                mns_val: vec![String::new(); 100],
                mnm_val: vec![0; 100],
                save_rcd_tick: 0,
            },
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: 42,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut world = mir2_world::World::new(8, 8);
        let mut displays = downlink::DisplayTable::new();

        // `recog=60001`（MakeIndex）、`param=0`（槽位）、`dealing=true`。
        handle_bag_cmd(
            game_svr::bag::CM_TAKEOFFITEM,
            60001,
            0,
            0,
            Some("木剑"),
            "hero",
            901,
            &online,
            &mut sessions,
            &gates,
            &catalog,
            &mut world,
            &mut displays,
            12,
            true,
            false,
        );
        let mut fail_seen = false;
        while let Ok(m) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, .. } = m {
                let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body).expect(">=12B");
                if cm.ident == mir2_protocol::messages::SM_TAKEOFF_FAIL {
                    assert_eq!(
                        cm.recog, -1,
                        "Dealing ⇒ n10 = -1（oracle Operate.cs:501/535）"
                    );
                    fail_seen = true;
                }
            }
        }
        assert!(fail_seen, "交易中卸装必须回 SM_TAKEOFF_FAIL(-1)");
        assert!(
            sessions.get("hero").unwrap().use_items[0].is_some(),
            "交易中不得真正卸下装备"
        );
    }

    /// **M3⑦-实现 4（M-1 收口）**：`deal_last_tick` 的**生产取数**被用例咬住——
    /// 交易会话 `DealLastTick` 未过 3000ms 门 ⇒ `CM_DROPITEM` 不得进 `ClientDropItem` 体。
    ///
    /// oracle：`PlayObject.Operate.cs:269`（`(HUtil32.GetTickCount() - DealLastTick) > 3000`
    /// 才进 `ItemList` 丢弃查表）；`DealLastTick` 字段见 `PlayObject.cs:122`。本仓
    /// `drop_item_down` 恒 false（`MapItem.ItemId == 0`，T-19），
    /// 故「是否进体」在成功/失败帧上不可分；可分的观测点是丢弃体里 `StdMode == 40` 的
    /// `Dura = (ushort)(Dura - 2000)` 原地扣减（`BaseObject.cs:541-548`，u16 回绕口径）。
    ///
    /// 改坏必红：把 `handle_ground_cmd` 里 `deal_last_tick` 的取数改回恒 `0` ⇒ 第一次调用即
    /// 过门、`Dura` 从 5000 变 3000 ⇒ `5000` 断言必红。
    #[test]
    fn drop_blocked_by_fresh_deal_last_tick() {
        use std::collections::HashMap;

        let mut world = mir2_world::World::new(32, 32);
        world.clock_ms = 10_000;
        let hero = world.add_entity({
            let mut e = mir2_world::Entity::new(1, "hero", 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e
        });

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert(
            "hero".into(),
            SessionGround {
                state: game_svr::ground::GroundState {
                    item_list: vec![game_svr::bag::BagItem {
                        make_index: 60001,
                        index: 1,
                        // `StdMode 40` 分支：`Dura 5000 - 2000 = 3000`。
                        dura: 5000,
                        dura_max: 5000,
                        desc: [0u8; 14],
                    }],
                    gold: 0,
                    wabil: test_ability(),
                },
                storage: storage::StorageState::new(),
                actor_id: hero,
                game_gold: 0,
                soft_version_date: 0,
                client_tick: 0,
                game_point: 0,
                sys_msg: None,
                use_items: vec![None; game_svr::ability::USE_ITEMS_LEN],
                sub: game_svr::ability::SubAbility::first_call(),
                hit_speed: 0,
                equip: test_equip_inputs(),
                recovery: game_svr::recover::Recovery::new(0),
                stamina: game_svr::stamina::Stamina::new(0),
                show_hp: false,
                abil_see_heal_gauge: false,
                user_unlock_durg: false,
                hunger_status: 0,
                query_bag_items_tick: None,
                bo_reconnection: false,
                bo_soft_close: false,
                bo_emergency_close: false,
                is_can_deal: true,
                click_npc_time: None,
                goto_npc_label: String::new(),
                val_type: 0,
                val_label: 0,
                val_npc_type: 0,
                mns_val: vec![String::new(); 100],
                mnm_val: vec![0; 100],
                save_rcd_tick: 0,
            },
        );
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, _rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let cfg = GroundCfg {
            human_max_gold: 10_000_000,
            floor_item_can_pick_up_time: 120_000,
            control_drop_item: false,
            in_safe_disable_drop: false,
            can_drop_price: 500,
            can_drop_gold: 1000,
            drop_item_rage: 3,
        };
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
        };
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "木剑".into(),
                std_mode: 40,
                ..Default::default()
            },
        );

        // 交易会话：`DealLastTick = now_tick`（`handle_deal_cmd` 写的是 `world.clock_ms`）。
        let mut trade_sessions: HashMap<String, game_svr::trade::DealState> = HashMap::new();
        trade_sessions.insert(
            "hero".into(),
            game_svr::trade::DealState {
                deal_last_tick: world.clock_ms,
                ..Default::default()
            },
        );

        // ① 新鲜 `DealLastTick` ⇒ `now - DealLastTick > 3000` 不成立 ⇒ 不进丢弃体 ⇒ Dura 不变。
        handle_ground_cmd(
            game_svr::ground::CM_DROPITEM,
            60001,
            0,
            Some("木剑"),
            "hero",
            901,
            &trade_sessions,
            &world,
            &mut sessions,
            &online,
            &gates,
            &cfg,
            &colors,
            &catalog,
            None,
        );
        assert_eq!(
            sessions.get("hero").unwrap().state.item_list[0].dura,
            5000,
            "3000ms 门内（交易中）⇒ ClientDropItem 体不得执行（oracle Operate.cs:269）"
        );

        // ② 过门（`DealLastTick` 陈旧）⇒ 进体 ⇒ StdMode40 原地扣 2000（u16 口径 5000→3000）。
        trade_sessions.get_mut("hero").unwrap().deal_last_tick = 1_000;
        handle_ground_cmd(
            game_svr::ground::CM_DROPITEM,
            60001,
            0,
            Some("木剑"),
            "hero",
            901,
            &trade_sessions,
            &world,
            &mut sessions,
            &online,
            &gates,
            &cfg,
            &colors,
            &catalog,
            None,
        );
        assert_eq!(
            sessions.get("hero").unwrap().state.item_list[0].dura,
            3000,
            "过 3000ms 门 ⇒ 进体 ⇒ Dura 5000-2000（BaseObject.cs:541-548）"
        );
    }

    /// **`openmir2-m3-selloff-consignment-world` 进程级判据**：走**生产路径** `handle_selloff_cmd`，
    /// 让卖方 L（gate 0 / socket 5）与买方 T（gate 1 / socket 6）完成
    /// `CM_SELLOFFADDITEM → CM_SELLOFFEND → CM_SELLOFFBUY`，断言：
    /// ① 帧按 `[gate_idx, socket]` 路由到正确连接；
    /// ② 上架扣 `DecUserGameGold=10000`、成交时买方 `-= nSellGold+10000`、卖方 `+= nSellGold`；
    /// ③ 上架回帧出队序 = `SM_MENU_OK(767) → SM_SELLOFFEND_OK(23016)`（优先级 69 < 233）；
    /// ④ 买方 = 立即 `SM_ADDITEM(200)` + 排队 `SM_WEIGHTCHANGED(622) → SM_GAMEGOLDNAME(5008)`；
    /// ⑤ `M2Share.SellOffItemList`（进程级 `SellOffBook`）跨会话共享（成交后 `flag=2`）。
    ///
    /// 红检：把 `handle_selloff_cmd` 的 `CM_SELLOFFEND` 支去掉、或把 `client_buy_sell_off_item`
    /// 的首次空槽中止删掉（让 `SM_SELLOFFBUY_OK` 出现）⇒ 本用例必 FAILED。
    #[test]
    fn selloff_cm_dispatch_emits_oracle_frames_on_both_connections() {
        use mir2_protocol::messages;
        use std::collections::HashMap;

        fn drain(rx: &mut mpsc::UnboundedReceiver<SimToGate>) -> Vec<Vec<u8>> {
            let mut out = Vec::new();
            while let Ok(ev) = rx.try_recv() {
                match ev {
                    SimToGate::SendFrame { body, .. } => out.push(body),
                    other => panic!("元宝寄售路径不得发 SendFrame 以外的命令，实得 {other:?}"),
                }
            }
            out
        }
        fn ident(body: &[u8]) -> u16 {
            u16::from_le_bytes([body[4], body[5]])
        }
        fn idents(frames: &[Vec<u8>]) -> Vec<u16> {
            frames.iter().map(|b| ident(b)).collect()
        }

        // 卖方 gate 0 / socket 5，买方 gate 1 / socket 6（按 `[gate_idx, socket]` 分流可区分）。
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let (tx1, mut rx1) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        gates.insert(1, tx1);

        let online: OnlineRegistry = vec![
            OnlineEntry {
                account: "a".into(),
                chr_name: "L".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: 1,
            },
            OnlineEntry {
                account: "b".into(),
                chr_name: "T".into(),
                session_id: 2,
                gate_idx: 1,
                socket: 6,
                actor_id: 2,
            },
        ];

        let weapon = game_svr::bag::BagItem {
            make_index: 100,
            index: 1,
            dura: 7,
            dura_max: 20,
            desc: [0; 14],
        };
        let mut seller = test_session_ground(1);
        seller.state.item_list.push(weapon);
        seller.state.wabil.weight = 0;
        seller.state.wabil.max_weight = 1000;
        seller.game_gold = 100_000;
        seller.soft_version_date = 1; // `SendGoldInfo` 门开（真客户端）
        let mut buyer = test_session_ground(2);
        buyer.state.wabil.weight = 0;
        buyer.state.wabil.max_weight = 1000;
        buyer.game_gold = 100_000;
        buyer.soft_version_date = 1;
        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        ground_sessions.insert("L".into(), seller);
        ground_sessions.insert("T".into(), buyer);
        let mut sell_off_sessions: HashMap<String, game_svr::selloff::SellOffState> =
            HashMap::new();
        let mut book = game_svr::selloff::SellOffBook::default();
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "木剑".into(),
                std_mode: 5,
                shape: 1,
                weight: 3,
                dura_max: 20,
                price: 10,
                ..mir2_data::StdItem::default()
            },
        );
        let cfg = game_svr::selloff::SellOffConfig::default();
        let world = mir2_world::World::new(32, 32);

        // ① 卖方把一件背包物品加进寄售窗（`CM_SELLOFFADDITEM`，`recog=MakeIndex`、尾=名字）
        handle_selloff_cmd(
            messages::CM_SELLOFFADDITEM,
            100,
            0,
            0,
            Some("木剑"),
            "L",
            5,
            &online,
            &world,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
            &gates,
            &cfg,
            &catalog,
        );
        assert_eq!(
            idents(&drain(&mut rx0)),
            vec![messages::SM_SELLOFFADDITEM_OK]
        );
        assert!(drain(&mut rx1).is_empty(), "买方不应收到上架回帧");
        assert_eq!(
            sell_off_sessions["L"].sell_off_item_list.len(),
            1,
            "物品应移进寄售临时列表"
        );
        assert!(
            ground_sessions["L"].state.item_list.is_empty(),
            "物品应移出背包"
        );

        // ② 上架（`CM_SELLOFFEND`，`recog=nSellGold`、尾=买方名）
        handle_selloff_cmd(
            messages::CM_SELLOFFEND,
            1000,
            0,
            0,
            Some("T"),
            "L",
            5,
            &online,
            &world,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
            &gates,
            &cfg,
            &catalog,
        );
        assert_eq!(
            idents(&drain(&mut rx0)),
            vec![messages::SM_MENU_OK, messages::SM_SELLOFFEND_OK],
            "上架出队序：MENU_OK(69) 先于 SELLOFFEND_OK(233)"
        );
        assert!(drain(&mut rx1).is_empty());
        assert_eq!(book.entries.len(), 1, "进程级 SellOffItemList 追加一条");
        assert_eq!(book.entries[0].deal_chr_name, "L");
        assert_eq!(book.entries[0].buy_chr_name, "T");
        assert_eq!(book.entries[0].sell_gold, 1000);
        assert_eq!(book.entries[0].flag, 0);
        assert_eq!(
            ground_sessions["L"].game_gold, 90_000,
            "上架扣 DecUserGameGold=10000"
        );

        // ③ 买方成交（`CM_SELLOFFBUY`，尾=卖方名）
        handle_selloff_cmd(
            messages::CM_SELLOFFBUY,
            0,
            0,
            0,
            Some("L"),
            "T",
            6,
            &online,
            &world,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
            &gates,
            &cfg,
            &catalog,
        );
        // 买方：立即 SM_ADDITEM(200) + 排队 131(WEIGHT) → 148(GAMEGOLD)。
        let buyer_frames = idents(&drain(&mut rx1));
        assert_eq!(
            buyer_frames,
            vec![
                messages::SM_ADDITEM,
                messages::SM_WEIGHTCHANGED,
                messages::SM_GAMEGOLDNAME,
            ]
        );
        // 卖方：只收一条元宝变化帧（`GameGoldChanged`）。
        assert_eq!(idents(&drain(&mut rx0)), vec![messages::SM_GAMEGOLDNAME]);
        assert_eq!(
            ground_sessions["T"].game_gold, 89_000,
            "买方扣 nSellGold(1000)+DecUserGameGold(10000)"
        );
        assert_eq!(
            ground_sessions["L"].game_gold, 91_000,
            "卖方 += nSellGold(1000)"
        );
        assert_eq!(
            ground_sessions["T"].state.item_list.len(),
            1,
            "物品进买方背包"
        );
        assert_eq!(book.entries[0].flag, 2, "成交后 flag=2（已售）");
        // 缺陷照搬①：`for j<=9` 首个空槽中止 ⇒ `SM_SELLOFFBUY_OK` 不可达。
        assert!(
            !buyer_frames.contains(&messages::SM_SELLOFFBUY_OK),
            "oracle 越界缺陷 ⇒ BUY_OK 恒不可达"
        );
    }

    /// **元宝寄售取消路径进程级判据**：走生产路径，分别驱动
    /// ① `CM_SELLOFFADDITEM → CM_SELLOFFEND → CM_SELLOFFBUYCANCEL`（买方取消 ⇒ `flag=3`
    ///    以及文案 `"取消交易成功!"`）；
    /// ② `CM_SELLOFFADDITEM → CM_SELLOFFEND → CM_CANCELSELLOFFITEMING`（卖方取消 ⇒ 事务条目移除、
    ///    物品退回背包；出队序 = 立即 `SM_ADDITEM`×2 → `SM_MENU_OK(69)`×2 → `SM_WEIGHTCHANGED(131)`）；
    ///    注意 oracle **不 break** ⇒ 同一卖方名下所有 `flag∈{0,3}` 的条目**一次全清**（连①的 flag=3 也退）。
    /// ③ `CM_SELLOFFDELITEM` / `CM_SELLOFFCANCEL` 的派发不 panic 且路由正确。
    ///
    /// 红检：把 `handle_selloff_cmd` 的 `CM_SELLOFFBUYCANCEL` 支去掉（`flag` 不变 3）⇒ ①②
    /// 的 flag 断言必 FAILED。
    #[test]
    fn selloff_cancel_paths_dispatch_and_mutate_global_book() {
        use mir2_protocol::messages;
        use std::collections::HashMap;

        fn drain(rx: &mut mpsc::UnboundedReceiver<SimToGate>) -> Vec<u16> {
            let mut out = Vec::new();
            while let Ok(ev) = rx.try_recv() {
                match ev {
                    SimToGate::SendFrame { body, .. } => {
                        out.push(u16::from_le_bytes([body[4], body[5]]));
                    }
                    other => panic!("元宝寄售路径不得发 SendFrame 以外的命令，实得 {other:?}"),
                }
            }
            out
        }

        let weapon = |mi: i32| game_svr::bag::BagItem {
            make_index: mi,
            index: 1,
            dura: 7,
            dura_max: 20,
            desc: [0; 14],
        };
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "木剑".into(),
                std_mode: 5,
                shape: 1,
                weight: 3,
                dura_max: 20,
                price: 10,
                ..mir2_data::StdItem::default()
            },
        );
        let cfg = game_svr::selloff::SellOffConfig::default();
        let world = mir2_world::World::new(32, 32);
        let online: OnlineRegistry = vec![
            OnlineEntry {
                account: "a".into(),
                chr_name: "L".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: 1,
            },
            OnlineEntry {
                account: "b".into(),
                chr_name: "T".into(),
                session_id: 2,
                gate_idx: 1,
                socket: 6,
                actor_id: 2,
            },
        ];
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let (tx1, mut rx1) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        gates.insert(1, tx1);

        let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut l = test_session_ground(1);
        l.state.wabil.weight = 0;
        l.state.wabil.max_weight = 1000;
        l.game_gold = 100_000;
        l.soft_version_date = 1;
        ground_sessions.insert("L".into(), l);
        let mut t = test_session_ground(2);
        t.game_gold = 100_000;
        t.soft_version_date = 1;
        ground_sessions.insert("T".into(), t);
        let mut sell_off_sessions: HashMap<String, game_svr::selloff::SellOffState> =
            HashMap::new();
        let mut book = game_svr::selloff::SellOffBook::default();

        // ① 买方取消：L 上架 → T 调 `CM_SELLOFFBUYCANCEL`（尾=卖方名）
        let call = |ident,
                    recog,
                    param,
                    tag,
                    tail: &str,
                    chr: &str,
                    socket,
                    ground: &mut HashMap<String, SessionGround>,
                    sessions: &mut HashMap<String, game_svr::selloff::SellOffState>,
                    book: &mut game_svr::selloff::SellOffBook| {
            handle_selloff_cmd(
                ident,
                recog,
                param,
                tag,
                Some(tail),
                chr,
                socket,
                &online,
                &world,
                ground,
                sessions,
                book,
                &gates,
                &cfg,
                &catalog,
            );
        };
        // 先给 L 背包放一件物品再上架。
        ground_sessions
            .get_mut("L")
            .unwrap()
            .state
            .item_list
            .push(weapon(100));
        call(
            messages::CM_SELLOFFADDITEM,
            100,
            0,
            0,
            "木剑",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        assert_eq!(drain(&mut rx0), vec![messages::SM_SELLOFFADDITEM_OK]);
        call(
            messages::CM_SELLOFFEND,
            1000,
            0,
            0,
            "T",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        let _ = drain(&mut rx0);
        assert_eq!(book.entries.len(), 1);
        call(
            messages::CM_SELLOFFBUYCANCEL,
            0,
            0,
            0,
            "L",
            "T",
            6,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        assert_eq!(
            drain(&mut rx1),
            vec![messages::SM_MENU_OK],
            "买方收取消回帧"
        );
        assert_eq!(book.entries[0].flag, 3, "买方取消 ⇒ Flag=3");

        // ② 卖方取消正在寄售中：重新上架一条 → L 调 `CM_CANCELSELLOFFITEMING`
        ground_sessions
            .get_mut("L")
            .unwrap()
            .state
            .item_list
            .push(weapon(200));
        call(
            messages::CM_SELLOFFADDITEM,
            200,
            0,
            0,
            "木剑",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        let _ = drain(&mut rx0);
        call(
            messages::CM_SELLOFFEND,
            1000,
            0,
            0,
            "T",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        let _ = drain(&mut rx0);
        call(
            messages::CM_CANCELSELLOFFITEMING,
            0,
            0,
            0,
            "",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        assert_eq!(
            drain(&mut rx0),
            vec![
                messages::SM_ADDITEM,
                messages::SM_ADDITEM,
                messages::SM_MENU_OK,
                messages::SM_MENU_OK,
                messages::SM_WEIGHTCHANGED,
            ],
            "取消寄售中：oracle 不 break ⇒ ①的 flag=3 条目也一并退回（2 次 AddItem/MENU_OK），\
             且 MENU_OK(69) 先于 WEIGHTCHANGED(131)"
        );
        assert!(
            book.entries.is_empty(),
            "同一卖方名下 flag∈{{0,3}} 的条目全部移除"
        );
        assert_eq!(
            ground_sessions["L"].state.item_list.len(),
            2,
            "两条目的物品都退回背包"
        );

        // ③ `CM_SELLOFFDELITEM` / `CM_SELLOFFCANCEL` 的派发（各回一帧）
        call(
            messages::CM_SELLOFFDELITEM,
            200,
            0,
            0,
            "木剑",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        assert_eq!(
            drain(&mut rx0),
            vec![messages::SM_SELLOFFDELITEM_FAIL],
            "列表里无此件 ⇒ FAIL"
        );
        ground_sessions
            .get_mut("L")
            .unwrap()
            .state
            .item_list
            .push(weapon(300));
        call(
            messages::CM_SELLOFFADDITEM,
            300,
            0,
            0,
            "木剑",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        let _ = drain(&mut rx0);
        call(
            messages::CM_SELLOFFCANCEL,
            0,
            0,
            0,
            "",
            "L",
            5,
            &mut ground_sessions,
            &mut sell_off_sessions,
            &mut book,
        );
        assert_eq!(drain(&mut rx0), vec![messages::SM_SellOffCANCEL]);
        assert!(sell_off_sessions["L"].sell_off_item_list.is_empty());
    }

    /// ⑤-4 第②片：`tail_encoded == true` 的帧（`SM_SAVEITEMLIST` 分页 / `SM_ADDITEM` 尾）走 oracle
    /// `SendSocket(ClientMsg, sMsg)` **直连**（`PlayObject.Socket.cs:104-127`），尾**不再**施加
    /// `EncodeString`。改坏（`emit_shop_frames` 忽略 `tail_encoded`、一律 `edcode::encode`）⇒ 本用例红。
    #[test]
    fn emit_shop_frames_keeps_pre_encoded_tail() {
        let (tx, mut rx) = mpsc::unbounded_channel();
        let raw = vec![0x3C_u8, 0x40, 0x7B, b'/'];
        let frames = vec![game_svr::shop::ShopFrame {
            ident: mir2_protocol::messages::SM_SAVEITEMLIST,
            recog: 4_242,
            param: 0,
            tag: 0,
            series: 0,
            tail: raw.clone(),
            tail_encoded: true,
        }];
        emit_shop_frames(&tx, 7, &frames);
        let (sock, body) = match rx.try_recv().expect("帧") {
            SimToGate::SendFrame { socket, body } => (socket, body),
            _ => panic!("非 SendFrame"),
        };
        assert_eq!(sock, 7);
        assert_eq!(
            &body[..12],
            &game_svr::smframe::command_header(
                4_242,
                mir2_protocol::messages::SM_SAVEITEMLIST,
                0,
                0,
                0
            )
        );
        assert_eq!(
            &body[12..],
            &raw[..],
            "直连尾原样下发（不重新 EncodeString）"
        );
    }

    /// **M3⑤-4 收口（T-47 ⑦）：`ClientUserBuyItem` 的 `Dealing` 前置门**
    /// （`PlayObject.Operate.cs:196-199` `if (Dealing) { return; }`，先于 `:200 FindMerchant`、
    /// 先于任何帧/副作用）。`CM_USERBUYITEM`/`CM_USERGETDETAILITEM` 在 oracle 里共用**同一方法体**
    /// （`Message.cs:897-902`）⇒ 两条都要过此门；其余五条商店命令 oracle 无此门。
    ///
    /// ⑦-3/⑦-4 落地后 `Dealing` 不再恒 `false` ⇒ 交易中买货/拉详情是**可达行为差异**。
    /// 判据：`trade_sessions[chr].dealing=true` ⇒ 两条命令零帧 + 金币/背包/库存全不变；
    /// 正对硪 `dealing=false` ⇒ 买入成功（回帧 + 扣金 100 + 加背包 + 库存减）。
    /// **改坏必红**：删掉 `handle_shop_cmd` 里的 `Dealing` 门 ⇒ 情形 A 出现买入帧且金币 500→400。
    #[test]
    fn shop_buy_and_detail_blocked_while_dealing() {
        use std::collections::HashMap;

        // —— 世界：玩家 (10,10) + 买入商人 (11,10)，在售 1 件 `Index=1` 的货。
        let mut world = mir2_world::World::new(32, 32);
        let hero = world.add_entity({
            let mut e = mir2_world::Entity::new(1, "hero", 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e
        });
        let merchant_id = world
            .insert_merchant(mir2_world::merchant::MerchantSpawn {
                name: "商人".to_string(),
                x: 11,
                y: 10,
                map_id: 0,
                state: mir2_world::merchant::MerchantState::new(
                    "卫家店".to_string(),
                    "0".to_string(),
                    0,
                    0,
                    100,
                    false,
                    false,
                    0,
                    mir2_world::merchant::MerchantFlags {
                        is_buy: true,
                        ..Default::default()
                    },
                    vec![0, 5],
                    Vec::new(),
                    0,
                ),
            })
            .expect("商人入世界");
        world.merchant_add_item_to_goods_list(
            merchant_id,
            mir2_world::merchant::MerchantItem {
                make_index: 7,
                index: 1,
                dura: 10,
                dura_max: 10,
                desc: [0; 14],
            },
        );

        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "金创药(小量)".to_string(),
                price: 100,
                weight: 3,
                std_mode: 0,
                dura_max: 10,
                ..mir2_data::StdItem::default()
            },
        );

        // —— 玩家会话：金币 500、负重 0/100（够买）。
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(hero);
        sg.state.gold = 500;
        sg.state.wabil.weight = 0;
        sg.state.wabil.max_weight = 100;
        sessions.insert("hero".to_string(), sg);
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".to_string(),
                chr_name: "hero".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut shop_sessions: HashMap<String, ShopSession> = HashMap::new();
        let mut sell_off_sessions: HashMap<String, game_svr::selloff::SellOffState> =
            HashMap::new();
        let mut sell_off_book = game_svr::selloff::SellOffBook::default();
        let shop_cfg = ShopCfg {
            castle_member_price_rate: 100,
            super_repair_price_rate: 100,
            repair_item_dec_dura: 0,
            make_durg_price: 100,
            get_all_npc_tax: false,
            human_max_gold: 10_000_000,
        };
        let mut item_number = 0i32;
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
        };

        // —— 情形 A：`Dealing=true` ⇒ 两条命令都零帧、零副作用。
        let mut trade_dealing: HashMap<String, game_svr::trade::DealState> = HashMap::new();
        trade_dealing.insert(
            "hero".to_string(),
            game_svr::trade::DealState {
                dealing: true,
                ..Default::default()
            },
        );
        handle_shop_cmd(
            game_svr::shop::CM_USERBUYITEM,
            merchant_id,
            0,
            0,
            Some("金创药(小量)"),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade_dealing,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            None,
            &mut item_number,
        );
        assert!(
            matches!(rx0.try_recv(), Err(mpsc::error::TryRecvError::Empty)),
            "Dealing ⇒ 买入不得发任何帧（oracle Operate.cs:196-199）"
        );
        assert_eq!(
            sessions.get("hero").unwrap().state.gold,
            500,
            "Dealing ⇒ 不得扣金"
        );
        assert!(
            sessions.get("hero").unwrap().state.item_list.is_empty(),
            "Dealing ⇒ 不得加背包"
        );
        assert_eq!(
            world.merchant_goods_groups(merchant_id).unwrap()[0].len(),
            1,
            "Dealing ⇒ 库存不动"
        );
        handle_shop_cmd(
            game_svr::shop::CM_USERGETDETAILITEM,
            merchant_id,
            1,
            0,
            Some("金创药(小量)"),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade_dealing,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            None,
            &mut item_number,
        );
        assert!(
            matches!(rx0.try_recv(), Err(mpsc::error::TryRecvError::Empty)),
            "Dealing ⇒ 详情列表不得发任何帧"
        );

        // —— 情形 B（正对照）：`Dealing=false` ⇒ 买入成功。
        let trade_open: HashMap<String, game_svr::trade::DealState> = HashMap::new();
        handle_shop_cmd(
            game_svr::shop::CM_USERBUYITEM,
            merchant_id,
            0,
            0,
            Some("金创药(小量)"),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade_open,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            None,
            &mut item_number,
        );
        let mut emitted = 0usize;
        while rx0.try_recv().is_ok() {
            emitted += 1;
        }
        assert!(emitted > 0, "非 Dealing ⇒ 应回买入帧");
        assert_eq!(
            sessions.get("hero").unwrap().state.gold,
            400,
            "非 Dealing ⇒ 扣金（100）"
        );
        assert_eq!(
            sessions.get("hero").unwrap().state.item_list.len(),
            1,
            "非 Dealing ⇒ 加背包"
        );
        assert!(
            world.merchant_goods_groups(merchant_id).unwrap().is_empty(),
            "非 Dealing ⇒ 库存减（空组移除）"
        );
    }

    /// **⑩-1 接线判据**：`Merchant.UserSelect` 的 `@dealybme` 支（`Merchant.cs:930-934`）已接线：
    /// `IsBDeal` 商人 + label `@dealybme` ⇒ `UserSelectOpenDealOffForm(playObject)`：
    /// 未开通 ⇒ `SM_MERCHANTSAY(643)`（`Recog`=商人 `ActorId`、`Param=Tag=0`、`Series=1`、
    /// 尾 = `EncodeString(GBK(商人名+'/'+text))`）；开通且无进行中 ⇒ `SM_SENDDEALOFFFORM(23001)`
    /// （`Recog`=商人 `ActorId`、`Param=0`）；`IsBDeal=false` ⇒ 零帧（oracle `if (IsYbDeal)` 门）。
    #[test]
    fn shop_dealybme_opens_consignment_form() {
        use std::collections::HashMap;

        let mut world = mir2_world::World::new(32, 32);
        let hero = world.add_entity({
            let mut e = mir2_world::Entity::new(1, "hero", 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e
        });
        let merchant_id = world
            .insert_merchant(mir2_world::merchant::MerchantSpawn {
                name: "商人".to_string(),
                x: 11,
                y: 10,
                map_id: 0,
                state: mir2_world::merchant::MerchantState::new(
                    "卫家店".to_string(),
                    "0".to_string(),
                    0,
                    0,
                    100,
                    false,
                    false,
                    0,
                    mir2_world::merchant::MerchantFlags {
                        is_yb_deal: true,
                        ..Default::default()
                    },
                    Vec::new(),
                    Vec::new(),
                    0,
                ),
            })
            .expect("商人入世界");

        let catalog = game_svr::ability::StdItemCatalog::new();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".to_string(), test_session_ground(hero));
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".to_string(),
                chr_name: "hero".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut shop_sessions: HashMap<String, ShopSession> = HashMap::new();
        let mut sell_off_sessions: HashMap<String, game_svr::selloff::SellOffState> =
            HashMap::new();
        let mut sell_off_book = game_svr::selloff::SellOffBook::default();
        let shop_cfg = ShopCfg {
            castle_member_price_rate: 100,
            super_repair_price_rate: 100,
            repair_item_dec_dura: 0,
            make_durg_price: 100,
            get_all_npc_tax: false,
            human_max_gold: 10_000_000,
        };
        let mut item_number = 0i32;
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
        };
        let trade: HashMap<String, game_svr::trade::DealState> = HashMap::new();

        // ---- ① 未开通 `SaleDeal` ⇒ `SM_MERCHANTSAY` 失败支①。
        handle_shop_cmd(
            game_svr::shop::CM_MERCHANTDLGSELECT,
            merchant_id,
            0,
            0,
            Some(game_svr::selloff::LABEL_DEAL_YB_ME),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            None,
            &mut item_number,
        );
        let body = match rx0.try_recv() {
            Ok(SimToGate::SendFrame { socket, body }) => {
                assert_eq!(socket, 901);
                body
            }
            _ => panic!("@dealybme 未开通 ⇒ 应回 1 帧商人说话"),
        };
        assert!(
            matches!(rx0.try_recv(), Err(mpsc::error::TryRecvError::Empty)),
            "@dealybme ⇒ 恰 1 帧"
        );
        assert_eq!(
            u16::from_le_bytes([body[4], body[5]]),
            mir2_protocol::messages::SM_MERCHANTSAY
        );
        assert_eq!(
            i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
            merchant_id,
            "Recog = 商人 ActorId"
        );
        assert_eq!(u16::from_le_bytes([body[6], body[7]]), 0, "Param=0");
        assert_eq!(u16::from_le_bytes([body[8], body[9]]), 0, "Tag=0");
        assert_eq!(u16::from_le_bytes([body[10], body[11]]), 1, "Series=1");
        let expect = mir2_protocol::edcode::encode(&game_svr::downlink::gbk(
            "商人/您未开通元宝服务,请先开通元宝服务!!\\ \\<返回/@main>",
        ));
        assert_eq!(
            &body[12..],
            &expect[..],
            "尾 = EncodeString(商人名+'/'+text)"
        );

        // ---- ② 开通且无进行中 ⇒ `SM_SENDDEALOFFFORM`。
        sell_off_sessions.get_mut("hero").unwrap().sale_deal = true;
        handle_shop_cmd(
            game_svr::shop::CM_MERCHANTDLGSELECT,
            merchant_id,
            0,
            0,
            Some(game_svr::selloff::LABEL_DEAL_YB_ME),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            None,
            &mut item_number,
        );
        let body = match rx0.try_recv() {
            Ok(SimToGate::SendFrame { socket, body }) => {
                assert_eq!(socket, 901);
                body
            }
            _ => panic!("@dealybme 开通 ⇒ 应回 1 帧开窗"),
        };
        assert_eq!(
            u16::from_le_bytes([body[4], body[5]]),
            mir2_protocol::messages::SM_SENDDEALOFFFORM
        );
        assert_eq!(
            i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
            merchant_id,
            "Recog = 商人 ActorId（32 位）"
        );
        assert_eq!(u16::from_le_bytes([body[6], body[7]]), 0, "Param=0");

        // ---- ③ `IsBDeal=false` ⇒ 零帧（oracle `if (IsBDeal)` 门）。
        world
            .entities
            .get_mut(merchant_id)
            .unwrap()
            .merchant
            .as_mut()
            .unwrap()
            .flags
            .is_yb_deal = false;
        handle_shop_cmd(
            game_svr::shop::CM_MERCHANTDLGSELECT,
            merchant_id,
            0,
            0,
            Some(game_svr::selloff::LABEL_DEAL_YB_ME),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            None,
            &mut item_number,
        );
        assert!(
            matches!(rx0.try_recv(), Err(mpsc::error::TryRecvError::Empty)),
            "IsBDeal=false ⇒ 不得开窗（oracle Merchant.cs:932）"
        );
    }

    // ===================== 入站派发 P0 批（R1 前六条）=====================

    /// **制药片 WB：`@makedrug` 面板 + `CM_USERMAKEDRUGITEM` 全链端到端**（经 `handle_shop_cmd`）。
    ///
    /// ① `CM_MERCHANTDLGSELECT("@makedrug")` + 制药商人 ⇒ 网关收一条 `SM_SENDUSERMAKEDRUGITEMLIST(712)`，
    ///    `Recog=ActorId`、尾 = `名/0/MakeDurgPrice/1/` 拼接。
    /// ② `CM_USERMAKEDRUGITEM("金创药")` ⇒ 三条帧
    ///    `SM_ADDITEM(200)` → `SM_DELITEMS(709)` → `SM_MAKEDRUG_SUCCESS(713, Recog=900)`；
    ///    金币 1000→900、材料消耗、成品入包。
    /// ③ 非制药商人 ⇒ 零帧。
    ///
    /// 变异必红：删掉 `CM_USERMAKEDRUGITEM` 臂（或 `handle_shop_cmd` 里的 `is_make_drug` 门）⇒ ①②/③ 必红。
    #[test]
    fn cm_usermakedrugitem_full_chain_over_gate() {
        use std::collections::HashMap;

        let mut world = mir2_world::World::new(32, 32);
        let hero = world.add_entity({
            let mut e = mir2_world::Entity::new(1, "hero", 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e
        });
        let merchant_id = world
            .insert_merchant(mir2_world::merchant::MerchantSpawn {
                name: "药商".to_string(),
                x: 11,
                y: 10,
                map_id: 0,
                state: mir2_world::merchant::MerchantState::new(
                    "药铺".to_string(),
                    "0".to_string(),
                    0,
                    0,
                    100,
                    false,
                    false,
                    0,
                    mir2_world::merchant::MerchantFlags {
                        is_make_drug: true,
                        ..Default::default()
                    },
                    vec![0, 5],
                    Vec::new(),
                    0,
                ),
            })
            .expect("制药商人入世界");
        // 在售组首件 = 成品「金创药」（`Index=3`）。
        world.merchant_add_item_to_goods_list(
            merchant_id,
            mir2_world::merchant::MerchantItem {
                make_index: 9,
                index: 3,
                dura: 12,
                dura_max: 12,
                desc: [0; 14],
            },
        );

        let mut catalog = game_svr::ability::StdItemCatalog::new();
        for (idx, name, price, dura) in [
            (3u16, "金创药", 100i32, 12u16),
            (4, "草药", 5, 5),
            (5, "布衣", 5, 5),
        ] {
            catalog.insert(
                idx,
                mir2_data::StdItem {
                    name: name.to_string(),
                    price,
                    weight: 1,
                    std_mode: 0,
                    dura_max: dura,
                    ..mir2_data::StdItem::default()
                },
            );
        }
        let make_reg =
            mir2_envir::makeitem::parse_make_item_lines("[金创药]\n草药 2\n布衣 1\n").unwrap();

        // —— 玩家会话：金币 1000、背包 2×草药 + 1×布衣。
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(hero);
        sg.state.gold = 1000;
        sg.state.item_list = vec![
            game_svr::bag::BagItem {
                make_index: 71,
                index: 4,
                dura: 0,
                dura_max: 0,
                desc: [0; 14],
            },
            game_svr::bag::BagItem {
                make_index: 72,
                index: 4,
                dura: 0,
                dura_max: 0,
                desc: [0; 14],
            },
            game_svr::bag::BagItem {
                make_index: 73,
                index: 5,
                dura: 0,
                dura_max: 0,
                desc: [0; 14],
            },
        ];
        sessions.insert("hero".to_string(), sg);
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".to_string(),
                chr_name: "hero".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut shop_sessions: HashMap<String, ShopSession> = HashMap::new();
        let mut sell_off_sessions: HashMap<String, game_svr::selloff::SellOffState> =
            HashMap::new();
        let mut sell_off_book = game_svr::selloff::SellOffBook::default();
        let shop_cfg = ShopCfg {
            castle_member_price_rate: 100,
            super_repair_price_rate: 100,
            repair_item_dec_dura: 0,
            make_durg_price: 100,
            get_all_npc_tax: false,
            human_max_gold: 10_000_000,
        };
        let mut item_number = 500i32;
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
        };
        let trade: HashMap<String, game_svr::trade::DealState> = HashMap::new();

        // —— ① `@makedrug` 面板。
        handle_shop_cmd(
            game_svr::shop::CM_MERCHANTDLGSELECT,
            merchant_id,
            0,
            0,
            Some("@makedrug"),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            Some(&make_reg),
            &mut item_number,
        );
        let panel = drain_frames(&mut rx0);
        assert_eq!(
            panel.len(),
            1,
            "① @makedrug ⇒ 一条 SM_SENDUSERMAKEDRUGITEMLIST"
        );
        let (ident, param, tag, recog) = hdr(&panel[0]);
        assert_eq!(ident, mir2_protocol::messages::SM_SENDUSERMAKEDRUGITEMLIST);
        assert_eq!(recog, merchant_id, "Recog=ActorId（商人）");
        assert_eq!((param, tag), (0, 0));
        assert_eq!(
            &panel[0][12..],
            &mir2_protocol::edcode::encode(&crate::downlink::gbk("金创药/0/100/1/")),
            "尾 = EncodeString(名/0/价/1/)"
        );

        // —— ② 制药请求：三条帧按发送序。
        handle_shop_cmd(
            game_svr::shop::CM_USERMAKEDRUGITEM,
            merchant_id,
            0,
            0,
            Some("金创药"),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            Some(&make_reg),
            &mut item_number,
        );
        let frames = drain_frames(&mut rx0);
        let idents: Vec<u16> = frames.iter().map(|b| hdr(b).0).collect();
        assert_eq!(
            idents,
            vec![
                mir2_protocol::messages::SM_ADDITEM,
                mir2_protocol::messages::SM_DELITEMS,
                mir2_protocol::messages::SM_MAKEDRUG_SUCCESS,
            ],
            "② 发送序 SM_ADDITEM → SM_DELITEMS → SM_MAKEDRUG_SUCCESS"
        );
        assert_eq!(
            hdr(&frames[2]).3,
            900,
            "SM_MAKEDRUG_SUCCESS 的 Recog = 扣后金币 900"
        );
        assert_eq!(
            hdr(&frames[1]).0,
            mir2_protocol::messages::SM_DELITEMS,
            "SM_DELITEMS 居中"
        );
        let g = sessions.get("hero").unwrap();
        assert_eq!(g.state.gold, 900);
        assert_eq!(g.state.item_list.len(), 1);
        assert_eq!(g.state.item_list[0].index, 3);
        assert_eq!(g.state.item_list[0].make_index, 501);

        // —— ③ 非制药商人（同一实体去掉 IsMakeDrug）⇒ 零帧、零副作用。
        {
            let st = world.entities.get_mut(merchant_id).unwrap();
            st.merchant.as_mut().unwrap().flags.is_make_drug = false;
        }
        handle_shop_cmd(
            game_svr::shop::CM_USERMAKEDRUGITEM,
            merchant_id,
            0,
            0,
            Some("金创药"),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut shop_sessions,
            &mut sell_off_sessions,
            &mut sell_off_book,
            &trade,
            &gates,
            &mut world,
            &catalog,
            &shop_cfg,
            &colors,
            Some(&make_reg),
            &mut item_number,
        );
        assert!(
            drain_frames(&mut rx0).is_empty(),
            "③ 非制药商人 ⇒ 零出帧（ClientMakeDrugItem 的 IsMakeDrug 门）"
        );
        assert_eq!(sessions.get("hero").unwrap().state.gold, 900, "③ 不得扣金");
    }

    /// **批 B 生产者（plan §4「W2 五帧的发射点」）：`CM_BUTCH` → `Command::Butch` → `SM_BUTCH(637)`** 端到端。
    ///
    /// `PlayObject.Operate.cs:749` 末尾**无条件** `SendRefMsg(RM_BUTCH, Dir, CurrX, CurrY, 0, "")`；
    /// `Dir` 仅在 `|Δx|<=2 && |Δy|<=2` 成立时更新为 `btDir`（`Operate.cs:729-747`），否则保持当前朝向。
    ///
    /// 变异必红：删掉 `CM_BUTCH` 臂里的 `world.enqueue(Command::Butch …)` ⇒ ①② 必红；
    /// 把方向恒取 `btDir`（无视 `|Δ|<=2` 门）⇒ ② 必红。
    #[test]
    fn cm_butch_enqueues_and_host_emits_sm_butch() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::new(32, 32);
        let mut pwd_sessions: std::collections::HashMap<String, game_svr::inbound::PwdSession> =
            std::collections::HashMap::new();
        let hero = world.add_entity({
            let mut e = mir2_world::Entity::new(1, "hero", 10, 10);
            e.race = mir2_world::ACTOR_RACE_PLAY;
            e.want_ref_msg = true;
            e
        });
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".to_string(), test_session_ground(hero));
        let mut online: OnlineRegistry = Vec::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".to_string(),
                chr_name: "hero".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let cfg = GroundCfg {
            human_max_gold: 10_000_000,
            floor_item_can_pick_up_time: 120_000,
            control_drop_item: false,
            in_safe_disable_drop: false,
            can_drop_price: 500,
            can_drop_gold: 1000,
            drop_item_rage: 3,
        };
        // 玩家当前朝向 = 2（展示表）。
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            hero,
            downlink::ActorDisplay::new(2, 0, 0, 0, 0, 255, Vec::new()),
        );

        // ① 目标格 (11,10) 在 2 格内 ⇒ `Dir = btDir = 5`。
        handle_inbound_cmd(
            &CommandMessage {
                recog: hero,
                ident: mir2_protocol::messages::CM_BUTCH,
                param: 11,
                tag: 10,
                series: 5,
            },
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            &mut pwd_sessions,
            &cfg,
            &displays,
        );
        let rec = world.tick();
        assert_eq!(rec.butches.len(), 1, "① CM_BUTCH ⇒ 一条 ButchEvent");
        assert_eq!(rec.butches[0].dir, 5, "① 2 格内 ⇒ Dir = btDir");
        assert_eq!((rec.butches[0].x, rec.butches[0].y), (10, 10));
        drain_action_downlink(&rec, &world, &displays, &online, &gates);
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "① 一条 SM_BUTCH(637)");
        let (ident, param, tag, recog) = hdr(&frames[0]);
        assert_eq!(ident, 637);
        assert_eq!(recog, hero);
        assert_eq!((param, tag), (10, 10), "Param/Tag = CurrX/CurrY");
        assert_eq!(
            u16::from_le_bytes([frames[0][10], frames[0][11]]),
            5,
            "① Series = Dir = btDir = 5"
        );

        // ② 目标格 (20,10) 超 2 格 ⇒ `Dir` 取当前朝向 2（**不取** btDir=7）。
        handle_inbound_cmd(
            &CommandMessage {
                recog: hero,
                ident: mir2_protocol::messages::CM_BUTCH,
                param: 20,
                tag: 10,
                series: 7,
            },
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            &mut pwd_sessions,
            &cfg,
            &displays,
        );
        let rec = world.tick();
        assert_eq!(rec.butches.len(), 1);
        assert_eq!(
            rec.butches[0].dir, 2,
            "② 超 2 格 ⇒ Dir 取当前朝向 2（不取 btDir=7）"
        );
        drain_action_downlink(&rec, &world, &displays, &online, &gates);
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1);
        assert_eq!(u16::from_le_bytes([frames[0][10], frames[0][11]]), 2);
    }

    /// 把一条 `SimToGate::SendFrame` 流排空成帧体列表（body 含 12B 命令头）。
    fn drain_frames(rx: &mut mpsc::UnboundedReceiver<SimToGate>) -> Vec<Vec<u8>> {
        let mut out = Vec::new();
        while let Ok(m) = rx.try_recv() {
            if let SimToGate::SendFrame { body, .. } = m {
                out.push(body);
            }
        }
        out
    }
    /// 从帧体取 `Ident`/`Param`/`Tag`。
    fn hdr(body: &[u8]) -> (u16, u16, u16, i32) {
        (
            u16::from_le_bytes([body[4], body[5]]),
            u16::from_le_bytes([body[6], body[7]]),
            u16::from_le_bytes([body[8], body[9]]),
            i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
        )
    }

    /// `CM_QUERYUSERNAME(80)`：近窗 ⇒ `SM_USERNAME`（尾 = `EncodeString(GetShowName())`）；
    /// 出窗 ⇒ `SM_GHOST`（x/y 原样回带、无尾）；目标不存在 ⇒ **不发帧**（oracle `baseObject == null` 早退）。
    ///
    /// 红检：把 `cetin_near_xy` 的窗口从 3×3 改宽/改窄 ⇒ ①/② 断言必红；删掉「目标不存在即 return」
    /// ⇒ ③ 断言必红；把 SM_GHOST 的 `x`/`y` 换成目标坐标 ⇒ ② 的红检必红。
    #[test]
    fn query_user_name_near_username_far_ghost_missing_no_frame() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map("hero", mir2_world::Entity::new(0, "hero", 10, 10), 0)
            .unwrap();
        world.open_session("tgt");
        let tgt = world
            .enter_map("tgt", mir2_world::Entity::new(0, "tgt", 11, 10), 0)
            .unwrap();

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = Vec::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            tgt,
            downlink::ActorDisplay::new(0, 0, 0, 0, 0, 255, b"TGT-SHOWN".to_vec()),
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        // ① 目标 (11,10) 落在以 (10,10) 为心的 3×3 ⇒ SM_USERNAME。
        handle_query_user_name_cmd(
            tgt, 10, 10, "hero", 901, &online, &sessions, &world, &displays, &gates,
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "近窗 ⇒ 恰好一帧");
        let (ident, param, tag, recog) = hdr(&frames[0]);
        assert_eq!(ident, mir2_protocol::messages::SM_USERNAME, "ident=42");
        assert_eq!(recog, tgt, "Recog=targetId");
        assert_eq!(param, 255, "Param=GetChrColor=255");
        assert_eq!(tag, 0);
        assert_eq!(
            mir2_protocol::edcode::decode(&frames[0][12..]),
            b"TGT-SHOWN",
            "尾 = EncodeString(GetShowName())"
        );

        // ② 目标不在窗口（心 (20,20)）⇒ SM_GHOST，x/y 原样回带、无尾。
        handle_query_user_name_cmd(
            tgt, 20, 20, "hero", 901, &online, &sessions, &world, &displays, &gates,
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "出窗 ⇒ 恰好一帧");
        let (ident, param, tag, recog) = hdr(&frames[0]);
        assert_eq!(ident, mir2_protocol::messages::SM_GHOST, "ident=803");
        assert_eq!(recog, tgt);
        assert_eq!(
            (param, tag),
            (20, 20),
            "SM_GHOST 的 Param/Tag = 请求 x/y 原样"
        );
        assert_eq!(frames[0].len(), 12, "SM_GHOST 无尾");

        // ③ 目标不存在 ⇒ 不发帧。
        handle_query_user_name_cmd(
            9999, 10, 10, "hero", 901, &online, &sessions, &world, &displays, &gates,
        );
        assert!(
            drain_frames(&mut rx0).is_empty(),
            "目标不存在 ⇒ oracle 早退，不发帧"
        );
    }

    /// `CM_QUERYUSERSTATE(82)`：近窗 ⇒ `SM_SENDUSERSTATE`（`Recog=0`），尾 = `EncodeBuffer(UserStateInfo)`；
    /// 目标的 UserStateInfo 头字段（Feature/UserName/NameColor）逐字段对上；非玩家目标 ⇒ 不发帧。
    ///
    /// 红检：把 `build_user_state_buffer` 的字段序换乱（如 NameColor 提到 UserName 前）⇒ 偏移断言必红；
    /// 删掉 `race == ACTOR_RACE_PLAY` 过滤 ⇒ 非玩家断言必红。
    #[test]
    fn query_user_state_frame_fields_and_non_player_guard() {
        use std::collections::HashMap;
        let mut world = mir2_world::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map("hero", mir2_world::Entity::new(0, "hero", 10, 10), 0)
            .unwrap();
        world.open_session("tgt");
        let tgt = world
            .enter_map("tgt", mir2_world::Entity::new(0, "tgt", 11, 10), 0)
            .unwrap();
        // 一只怪（非玩家）目标，验「非玩家 ⇒ 不发帧」。
        let mon = world.add_entity({
            let mut e = mir2_world::Entity::new(0, "mon", 11, 11);
            e.race = mir2_world::ACTOR_RACE_MONSTER;
            e
        });
        world.tick();

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        sessions.insert("tgt".into(), test_session_ground(tgt));
        let mut online: OnlineRegistry = Vec::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let catalog = game_svr::ability::StdItemCatalog::new();

        handle_query_user_state_cmd(
            tgt, 10, 10, "hero", 901, &online, &sessions, &world, &gates, &catalog,
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "近窗玩家 ⇒ 恰好一帧");
        let (ident, _, _, recog) = hdr(&frames[0]);
        assert_eq!(
            ident,
            mir2_protocol::messages::SM_SENDUSERSTATE,
            "ident=751"
        );
        assert_eq!(recog, 0, "SM_SENDUSERSTATE 的 Recog=0");
        // 尾 = EncodeBuffer(UserStateInfo) ⇒ 解出 1:1 的 UserStateInfo 缓冲。
        let tail = mir2_protocol::edcode::decode(&frames[0][12..]);
        let item_len = queryuser::null_item_buffer().len();
        assert_eq!(
            tail.len(),
            60 + 13 * item_len + 1 + 15,
            "UserStateInfo 缓冲长度（空背包 13 空槽）"
        );
        let feature = game_svr::feature::human_feature(None, None, 0, 0);
        assert_eq!(
            &tail[0..4],
            &feature.to_le_bytes(),
            "Feature @0（空装备/性别 0/发型 0）"
        );
        assert_eq!(tail[4], 3, "UserName='tgt' 长度=3 @4");
        assert_eq!(&tail[5..8], b"tgt", "UserName 内容");
        assert_eq!(&tail[20..24], &255i32.to_le_bytes(), "NameColor=255 @20");

        // 非玩家目标 ⇒ 不发帧。
        handle_query_user_state_cmd(
            mon, 10, 10, "hero", 901, &online, &sessions, &world, &gates, &catalog,
        );
        assert!(
            drain_frames(&mut rx0).is_empty(),
            "非玩家目标 ⇒ 不发帧（登记：C# 抛 InvalidCastException）"
        );
    }

